(window.__BOOKS=window.__BOOKS||{})["e_orestes"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"elektra\">Электра</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"elena\">Елена</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Хор из пятнадцати аргосских женщин</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"orest\">Орест</span></span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"menelay\">Менелай</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"tindar\">Тиндар</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Вестник, старый микенец</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"pilad\">Пилад</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Гермиона</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Фригиец, евнух</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Аполлон</span> <span class=\"act-no\">(II)</span>"],["place","Действие происходит в Аргосе, спустя пять дней после сожжения тела Клитемнестры."],["act","Пролог","a1",""],["sd","Перед дворцом Агамемнона, на низком ложе спит тяжким тревожным сном <span class=\"ch\" data-ch=\"orest\">Орест</span>, закрытый пурпуровым пеплосом. В ногах <span class=\"ch\" data-ch=\"elektra\">Электра</span>, в темном, худая, бледная, остриженная. Утро."],["scene","Явление первое","s1",1,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Где мука та, которую назвать —",0,1,0,0],["v","Так стынет кровь, и где та кара, люди,",0,1,0,0],["v","Божественным решенная судом,",0,1,0,0],["v","Чтоб ваших плеч их иго миновало?",0,1,0,0],["sd","Пауза."],["v","Блаженный царь — о да! Уста хулы",0,2,0,0],["v","Не изрекут, назвав его блаженным,",0,3,0,0],["v","Кронидов сын — как говорит молва —",0,4,0,0],["v","Там, в воздухе парит недвижно Тантал…",0,5,0,0],["v","И ужасом терзается, скалу",0,6,0,0],["v","Над головою чувствуя преступной…",0,7,0,0],["v","Позорнейший недуг тому виной:",0,8,0,0],["v","С богами сев за трапезу, как равный,",0,9,0,0],["v","С надменным царь не сладил языком.<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,10,0,1],["sd","Пауза."],["v","Ему Пелоп наследовал, а внуку",0,10,0,0],["v","Блаженного, Атрею, в нить его",0,11,0,0],["v","Вражду впряла божественная Мойра,",0,11,0,0],["v","Назначивши с Фиестом воевать,",0,12,0,0],["v","Единокровным братом.",0,13,0,0],["v","Надо ль свиток",1,13,0,0],["v","Мне развивать позорный? Да, Атрей",0,13,0,0],["v","Отцу скормил детей…",0,14,0,0],["v","Пауза, потом быстрее.",0,15,0,0],["v","Пропустим лучше",0,15,4,0],["v","Подробности… Атреем рождены",0,16,0,0],["v","Агамемнон прославленный — коль точно",0,16,0,0],["v","Он славен был! — и <span class=\"ch\" data-ch=\"menelay\">Менелай</span>, а мать",0,17,0,0],["v","Одна носила их, из Крита родом,",0,18,0,0],["v","А звалась Аэропа. <span class=\"ch\" data-ch=\"menelay\">Менелай</span>",0,18,0,0],["v","Женился на <span class=\"ch\" data-ch=\"elena\">Елене</span>, ненавистной",0,19,0,0],["v","Богам, а брат его, Агамемнон,",0,20,0,1],["v","Ее сестры сияющее ложе",0,20,0,0],["v","Меж эллинов приемлет. Нас у ней",0,21,0,0],["v","Три девы родилось: Хрисофемида,",0,22,0,0],["v","Да Ифигения, да я, Электра…",0,23,0,0],["v","Да сын <span class=\"ch\" data-ch=\"orest\">Орест</span>…",0,24,0,0],["v","У матери преступной,",1,24,0,0],["v","Которая предательским плащом",0,25,0,0],["v","Опутала Атрида — и убила.",0,25,0,0],["sd","Пауза."],["v","Из-за чего? Не подобает деве",0,26,0,0],["v","Здесь объяснять… другие разберут…",0,27,0,0],["v","…<span class=\"ch\" data-ch=\"orest\">Оресту</span> Феб — не в осужденье это",0,28,0,0],["v","Я говорю — велел зарезать мать…",0,29,0,0],["v","И сын, хотя блестящим это дело",0,30,0,1],["v","Немногие сочтут, покорный богу,",0,30,0,0],["v","Покончил с нею; женщина, а все ж",0,31,0,0],["v","Я помогала брату, да <span class=\"ch\" data-ch=\"pilad\">Пилад</span>",0,32,0,0],["v","В товарищах был с нами…",0,33,0,0],["sd","Пауза. Тихо."],["v","И, свирепым",1,33,0,0],["v","Снедаемый недутом, с той поры",0,34,0,0],["v","Лежит <span class=\"ch\" data-ch=\"orest\">Орест</span> на этом ложе: кровь",0,35,0,0],["v","Из матери зарезанной несчастным,",0,35,0,0],["v","Как обручем, играет… Называть",0,36,0,0],["v","Я не хочу Эриний, что <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,37,0,0],["v","Одна перед другой изводят страхом.",0,38,0,0],["v","Шестой уж день, с тех пор как под ножом",0,39,0,0],["v","Умершая очищена сожженьем,",0,40,0,1],["v","Не проглотил куска он, омовеньем",0,40,0,0],["v","Ни разу кожи он не освежил.",0,41,0,0],["v","Лишь, завернувшись в плащ, когда отпустит",0,42,0,0],["v","Недуг его, опомнится и плачет…",0,43,0,0],["v","А то порой, с постели соскочив,",0,44,0,0],["v","Как лошадь, сбившая ярмо, сорвется…",0,45,0,0],["sd","Пауза."],["v","В опале мы. От Аргоса указ:",0,45,0,0],["v","Все двери запереть для нас, жаровни",0,46,0,0],["v","Загородить от грешных и уста",0,47,0,0],["v","От сообщенья с ними. А сегодня",0,48,0,0],["v","На сборище аргосцы порешат:",0,49,0,0],["v","Побить ли нас каменьями иль шеи",0,50,0,1],["v","Под острый нож приличнее сложить…",0,50,0,0],["v","Но есть еще надежда детям царским,",0,51,0,0],["v","А в чем она, сейчас скажу: сюда",0,52,0,0],["v","Мы дядю ждем, — он гавани навплийской",0,53,0,0],["v","Уже достиг. Немало по морям",0,54,0,0],["v","Скитался <span class=\"ch\" data-ch=\"menelay\">Менелай</span>, покинув Трою;",0,55,0,0],["v","Уже, под кровом ночи, в наш чертог",0,56,0,0],["v","Он переслал царицу слез, Елену, —",0,57,0,0],["v","Опасно днем казалось: у кого",0,58,0,0],["v","Под Троею убили сына, камень",0,59,0,0],["v","Давно, поди, на случай припасал…",0,60,0,1],["v","Теперь <span class=\"ch\" data-ch=\"elena\">Елена</span> в доме — над сестрой",0,60,0,0],["v","И над бедой семейной нашей плачет…",0,61,0,0],["v","Но есть и ей отрада, — с нею здесь",0,62,0,0],["v","Дочь-девушка — перед войной отец",0,63,0,0],["v","К покойнице доставил Гермиону.",0,64,0,0],["v","Посмотрит на нее <span class=\"ch\" data-ch=\"elena\">Елена</span>-мать",0,65,0,0],["v","И улыбнется и печаль забудет.<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,66,0,0],["sd","Пауза."],["v","А <span class=\"ch\" data-ch=\"menelay\">Менелая</span> нет… безмолвна даль,",0,67,0,0],["v","И ненадежна наша колесница…",0,68,0,0],["v","Коль он теперь не выручит, едва ль",0,69,0,0],["v","Тебе, о дом злосчастный, возродиться!",0,70,0,1],["sd","(Идет к ложу <span class=\"ch\" data-ch=\"orest\">Ореста</span> и садится по-прежнему в ногах, закрыв лицо руками.)"],["scene","Явление второе","s2",1,2],["sd","Из дома выходит <span class=\"ch\" data-ch=\"elena\">Елена</span>, нарядная, завитая. За ней свита рабынь и евнухов с опахалами, флаконами и зеркалами."],["sd","<span class=\"ch\" data-ch=\"elena\">Елена</span> и <span class=\"ch\" data-ch=\"elektra\">Электра</span>. (<span class=\"ch\" data-ch=\"orest\">Орест</span> спит на ложе; в конце явления — Гермиона, без участия в действии.)"],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","увидев <span class=\"ch\" data-ch=\"elektra\">Электру</span>, которая при первых звуках ее голоса отнимает руки от лица, — останавливается поодаль"],["sd","Свита смотрит на брата и сестру с насмешливым любопытством."],["v","Атрида дочь, дитя сестры моей,",0,70,0,0],["v","В девичестве застывшая <span class=\"ch\" data-ch=\"elektra\">Электра</span>,",0,71,0,0],["v","Скажи, какой вам демон нашептал?..",0,72,0,0],["v","Кто этого несчастного <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,73,0,0],["v","Зарезать мать родную обезумил?",0,73,0,0],["v","Беседою с тобою я себя",0,74,0,0],["v","Не оскверняю, нет, — и грех на Феба",0,75,0,0],["v","Переношу охотно… О сестре",0,76,0,0],["v","Как не скорбеть? Мы не видались с нею",0,76,0,0],["v","С тех самых пор, как тяжкий гнев богов",0,77,0,0],["v","Меня обрек триере Илионской…",0,78,0,0],["v","Да, гнев богов… Но больше нет сестры,",0,79,0,0],["v","И жребий ваш теперь мне жалок, дети!",0,80,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","сидя"],["v","На что слова, Елена? Если ты",0,80,0,0],["v","Не видела семьи Агамемнона",0,81,0,0],["v","Злосчастия… полюбоваться можешь:",0,82,0,0],["v","Вот день и ночь у трупа сторожу…",0,83,0,0],["v","Иль не мертвец? Дыханья не уловишь.",0,84,0,0],["v","Так и сижу… не мне судьею быть",0,85,0,0],["v","Ему… А с вас, блаженных, не довольно ль",0,86,0,0],["v","Увидеть нас, измученных бедой?",0,87,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","присматриваясь к <span class=\"ch\" data-ch=\"orest\">Оресту</span>"],["v","Давно ли он в постели-то, Электра?",0,88,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","С тех пор как кровь родимую пролил.",0,89,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Несчастный сын! А мать — какою смертью!..",0,90,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Да, чаша зол с краями налита.",0,91,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","помолчав"],["v","А я пришла просить твоей услуги.",0,92,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Я при больном, но если я урвусь…",0,93,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","перебивая ее"],["v","То посетишь могилу Клитемнестры…",0,94,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","мрачно"],["v","Гроб матери моей?.. А для чего?",0,95,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ты локон мой снесешь ей и фиалы.",0,96,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль сестрин прах тебе самой не мил?",0,97,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Краснею я ахейцам показаться.",0,98,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Немножко поздно вздумала краснеть.",0,99,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О, ты права, но бессердечна, дева!",0,100,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Тебе микенцев стыдно отчего ж?",0,101,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Здесь есть отцы под Илионом павших.",0,102,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Да, точно, здесь у всех ты на устах.",0,103,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Вот видишь ты. Так выручи ж, <span class=\"ch\" data-ch=\"elektra\">Электра</span>.",0,104,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Глядеть на гроб ее — о, не проси.",0,105,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","нетерпеливо"],["v","Или послать рабыню мне прикажешь?",0,106,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Но у тебя есть дочь: ее пошли.",0,107,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","В толпу пускать ребенка неудобно…",0,108,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Покойная ей заменяла мать…",0,109,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","обращаясь к терему"],["v","Пожалуй, ты права. Дитя мое,",0,110,0,1],["v","Сойди сюда. Фиалы, Гермиона,",0,110,0,0],["sd","Гермиона показывается из ворот; согласно словам <span class=\"ch\" data-ch=\"elena\">Елены</span>, рабыни передают ей от <span class=\"ch\" data-ch=\"elena\">Елены</span> фиалы и прядь волос."],["v","И прядь волос моих ты бережно возьмешь",0,111,0,0],["v","И, посетив могилу Клитемнестры,",0,112,0,0],["v","Там медомлечьем с пеною вина",0,113,0,0],["v","Гробницу ей ты оросишь и скажешь",0,114,0,0],["v","С могильной насыпи, что это я",0,115,0,0],["v","Ее дарю надгробным возлияньем",0,116,0,0],["v","И что, — увы! — боясь аргосской черни,",0,117,0,0],["v","Не <em>смею</em> я слезой ее почтить.",0,118,0,0],["v","Моли, дитя, благословенья мертвой",0,119,0,0],["v","Ко мне, и к вам с отцом, и к этим горьким,",0,120,0,1],["v","Которых бог сгубил; ты обещай",0,120,0,0],["v","Ей именем моим все приношенья,",0,121,0,0],["v","Что подобают мертвым, но, свершив",0,122,0,0],["v","На гробе возлияние, не медли!",0,123,0,0],["sd","(Подходит к выжидающей Гермионе и удаляется вместе с нею, в сопровождении свиты.)"],["scene","Явление третье","s3",1,3],["v","<span class=\"ch\" data-ch=\"elektra\">Электра</span> и <span class=\"ch\" data-ch=\"orest\">Орест</span> (спящий).",0,124,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","смотря вслед уходящей <span class=\"ch\" data-ch=\"elena\">Елене</span>"],["v","О, сколько зла в тебе, природа смертных!",0,125,0,0],["v","Иль столько ж благ ты избранным даришь?",0,126,0,0],["v","Вы видели, красу оберегая,",0,127,0,0],["v","Волос ее едва коснулся нож.",0,128,0,0],["v","О, ты все та же, женщина!..",0,129,0,0],["v","Но боги",1,129,0,0],["v","Тебе отплатят, верю, за меня,",0,130,0,1],["v","И за него (указывая на <span class=\"ch\" data-ch=\"orest\">Ореста</span>) и за Элладу… Горе!",0,131,0,0],["v","О, горе мне!.. Что вижу? К нам идут",0,132,0,0],["v","Подруги слез моих… Что, если, горе",0,133,0,0],["v","Мое деля, они разбудят брата",0,134,0,0],["v","И в ужасе придется мне опять",0,135,0,0],["v","Глядеть на эти приступы безумья?..",0,136,0,0],["scene","Явление четвертое","s4",1,4],["sd","Электра, <span class=\"ch\" data-ch=\"orest\">Орест</span> (спящий) и хор (подходит со стороны; издали видя <span class=\"ch\" data-ch=\"elektra\">Электру</span> в черном и остриженную, женщины выражают жестами и возгласами сострадание). <span class=\"ch\" data-ch=\"elektra\">Электра</span> (которая села после ухода <span class=\"ch\" data-ch=\"elena\">Елены</span>, теперь, не сходя с места, протягивает к ним руки ладонями вперед)."],["v","О, тише, тише, женщины, шуметь",0,137,0,0],["v","Не надо здесь. Ни звука, ради бога!",0,138,0,0],["v","Мне сладостен ваш ласковый привет,",0,139,0,0],["v","Но разбудить безумного — несчастье…",0,140,0,0],["scene","Вступительная песнь хора","s5",1,5],["sp","Хор"],["sd","Строфа I 140 Тише… тише… Легче ступай, сестра! Шелестом… Шорохом…"],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Дальше… Дальше… от ложа, вы…",0,141,0,0],["sp","Хор"],["v","Слышим, царевна.",0,142,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Тихий, как вздохи свирели,",0,143,0,0],["v","Сладостен будет мне голос…",0,144,0,0],["sp","Хор"],["v","Точно под крышей, зов мой задушен.",0,145,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Так хорошо…",0,146,0,0],["v","Шепотом, сестры, легче теней",0,147,0,0],["v","К уху приблизьтесь: что привело вас?",0,150,0,1],["v","Еле уснул он — долго томился…",0,151,0,0],["sp","Хор"],["sd","Антистрофа I Что с ним?.. Что с ним?.. Или беда стряслась? Или попритчилось?.."],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","наклоняясь к спящему"],["v","Дышит… Стоны прерывисты…",0,152,0,0],["sp","Хор"],["dir","со вздохами"],["v","Бедный царевич!",0,153,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","С век его если дремоту",0,154,0,0],["v","Свеешь, ты будешь убийцей.",0,155,0,0],["sp","Хор"],["v","Это злодейство — божье веленье.",0,160,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Божье, увы!",0,161,0,0],["v","Несправедлив был Феб-Аполлон:",0,162,0,0],["v","Ужас убийства матери нашей",0,163,0,0],["v","Правым назвал он с трона Фемиды.",0,164,0,0],["sp","Хор"],["sd","Строфа II Посмотри… под одеждой… задвигался."],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Это ты… Это ты",0,165,0,0],["v","Подняла его криком, несчастная.",0,166,0,0],["sp","Хор"],["v","Мне казалось, что спит он.",0,167,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","приподнимаясь"],["v","Ради богов! Или опять",0,170,0,1],["v","К ложу приблизишь ты",0,171,0,0],["v","Топот идущих ног?",0,172,0,0],["sp","Хор"],["sd","В воздухе поднимаются вторые пальцы, в знак предостережения."],["v","Он задремал…",0,173,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","шепотом, не отрывая глаз от <span class=\"ch\" data-ch=\"orest\">Ореста</span>"],["v","Кажется, да.",1,173,0,0],["sd","(После короткой паузы <span class=\"ch\" data-ch=\"elektra\">Электра</span> приподнимается, потом встает, делает несколько шагов и простирает к небу руки.)"],["v","Ночь, владычица мира, ночь!",0,174,0,0],["v","Смертным страдальцам сон ты даруешь.",0,175,0,0],["v","Крылья развей, богиня, царство Эреба покинув.",0,176,0,0],["v","К дому слети Атрида,",0,177,0,0],["v","Где от беды и скорби",0,180,0,1],["v","Гибнем мы, ночь, гибнем.",0,181,0,0],["sd","В хоре ее мольба производит движение; шум усиливается."],["v","Ах, эти стуки… Или, молчаньем",0,182,0,0],["v","Голос сковавши, сонной услады",0,183,0,0],["v","Брату, подруги, дать не хотите?",0,184,0,0],["sp","Хор"],["sd","Антистрофа II О, когда ж эти беды покончатся?"],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Как умрет — и конец.",0,185,0,0],["v","Уж и то, занедужив, не пьет, не ест.",0,186,0,0],["sp","Хор"],["v","Разве к смерти он близок?",0,190,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Нас Аполлон в жертву принес,",0,191,0,0],["v","Отцеубийственной.",0,192,0,0],["v","Кровью забрызганных…",0,193,0,0],["sp","Хор"],["v","Праведен суд.",0,194,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Да не судья…",1,194,0,0],["v","Мать, — и жертва, и жрица — мать!",0,195,0,0],["v","Жизнь подарила, чтобы потом нас,",0,196,0,0],["v","Кровью твоей вспоенных, осиротив, зарезать.",0,197,0,0],["v","Сгибли мы, мать, мы мертвы.",0,200,0,1],["v","К трупу припав, <span class=\"ch\" data-ch=\"elektra\">Электра</span>",0,201,0,0],["v","В стонах свой век тратит.",0,202,0,0],["v","Целые ночи плачет царевна,",0,203,0,0],["v","Мужа не зная, детскою лаской",0,204,0,0],["v","В медленной жизни сердца не грея.",0,205,0,0],["act","Действие первое","a2","I"],["scene","Явление пятое","s6",2,6],["sd","Те же и <span class=\"ch\" data-ch=\"orest\">Орест</span>, который вступает в действие после первых слов корифея."],["sp","Корифей"],["dir","приближаясь к <span class=\"ch\" data-ch=\"elektra\">Электре</span>"],["v","Электра, ты — поближе — погляди,",0,206,0,0],["v","Уж не скончался ль брат: его чрезмерный,",0,207,0,0],["v","Размаянный покой меня страшит…",0,210,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","открывает глаза, потом закрывает их, потом, снова открыв их, приподнимается и смотрит перед собой, не стараясь еще дать себе отчета в окружающем"],["v","О сладкий сон-целитель, ты к больному",0,211,0,0],["v","Так вовремя, так ласково слетел!",0,212,0,0],["v","О, забытье, богиня несчастливцев!",0,213,0,0],["sd","(Оглядывается.)"],["v","Но как сюда пришел? Зачем пришел?",0,214,0,0],["v","Не помню… И рассудком я покинут…",0,215,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","подходя к нему, ласково"],["v","Твой сон, Орест, и мне отрадой был.",0,216,0,0],["v","Не хочешь ли: тебя приподниму я?",0,217,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","утомленно опускается на ложе"],["v","О да! Возьми меня — и с жалких губ,",0,218,0,0],["v","И с век моих сотри остатки пены.",0,220,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Мне радостно служить тебе, Орест,",0,221,0,0],["v","И тело братское твое покоить…",0,222,0,0],["sd","(Становится возле него на колени.)"],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я голову склоню тебе на грудь:",0,223,0,0],["v","Сними волос завесу мне — не вижу.",0,224,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","кладет голову его себе на грудь и разбирает ему волосы"],["v","О, жалкая, давно ты, голова,",0,225,0,0],["v","Воды не знала: волосы слежались…",0,226,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","утомленно"],["v","Нет, положи опять… Когда недуг",0,227,0,0],["v","Отпустит — тело слабо и разбито…",0,228,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Ложись. Постель недужному мила:",0,229,0,0],["v","Печальная, но верная подруга.",0,230,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Опять меня по-старому возьми:",0,231,0,0],["v","Нетерпелив больной и беспокоен.",0,232,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","А может быть, и ноги спустишь ты,",0,233,0,0],["v","И медленно походим мы. Попробуй.",0,234,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","садится при помощи <span class=\"ch\" data-ch=\"elektra\">Электры</span>, но жестом отклоняет ее, когда она хочет заставить его встать"],["v","Да, хорошо. Когда здоровья нет,",0,235,0,0],["v","По крайней мере, с виду ты как люди.",0,236,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Послушай-ка, родимый мой, пока",0,237,0,0],["v","Твой ум еще Эринии не мучат…",0,238,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Коль хороши слова, так говори,",0,239,0,0],["v","Но если нет — с меня довольно горя.",0,240,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Отцовский брат приехал, Менелай, —",0,241,0,0],["v","Уж в гавани суда его навплийской.",0,242,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что говоришь? Ведь это был бы свет,",0,243,0,0],["v","Спасенья свет: родной… отцу обязан…",0,244,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Не веришь мне — залогу верь: с собой",0,245,0,0],["v","<span class=\"ch\" data-ch=\"elena\">Елену</span> он привез из стен троянских…",0,246,0,0],["sd","Пауза. <span class=\"ch\" data-ch=\"orest\">Орест</span> становится задумчив. <span class=\"ch\" data-ch=\"elektra\">Электра</span> глазами следит за ним."],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Вернись один, он был бы нам милей,",0,247,0,0],["v","Но с ним жена: всех бед <span class=\"ch\" data-ch=\"elena\">Елена</span> горше.",0,248,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Да, царь <span class=\"ch\" data-ch=\"tindar\">Тиндар</span> породой дочерей",0,249,0,0],["v","Себе добыл в Элладе злую славу.",0,250,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","мрачно"],["v","Из них вольна ты исключеньем быть…",0,251,0,0],["v","Не на словах, конечно, а душою…",0,252,0,0],["sd","(Откидывается на постель, потом вскакивает, на губах показывается пена, глаза тревожно блуждают.)"],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","про себя"],["v","Увы! Опять мутится взор… Сейчас",0,253,0,0],["v","Он был здоров… И снова ум теряет…",0,254,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я умоляю, мать, не насылай",0,255,0,0],["v","Их на меня — не волосы, а змеи,",0,256,0,0],["v","Лицо в крови: я узнаю их — скачут.",0,257,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","старается уложить его"],["v","Лежи, несчастный брат, ты ничего",0,258,0,0],["v","Не видишь… Это грезы, только грезы…",0,259,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","освобождается от ее руки"],["v","О Феб! Они убьют меня — лицо",0,260,0,1],["v","Собачье, а глаза Горгоны, в жертву",0,260,0,0],["v","Они приносят богу мертвецов.<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,261,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","кладет его на постель, пользуясь минутой утомленья, и держит по поясу"],["v","Не выпущу… лежи — обвив рукой,",0,262,0,0],["v","Тебе не дам ни прыгать, ни метаться.",0,263,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","борется с ней и наконец освобождается, во время борьбы он кричит"],["v","Пусти… ты, ты — Эриния — меня",0,264,0,0],["v","Ты обняла теперь, чтоб бросить в Тартар.",0,265,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","отходит плача"],["v","Увы! Увы! Сам бог на нас; искать",0,266,0,0],["v","Защиты где, ума не приложу.",0,267,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","сопровождая слова мимической сценой бреда"],["v","Подай мне лук из рога, Аполлонов",0,268,0,0],["v","Подарок: он велел мне отгонять",0,269,0,0],["v","Богинь, когда, волнуя гневом душу,<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,270,0,1],["v","Мне будут докучать. Сейчас одну",0,271,0,0],["v","Из них я раню, да, богиню — смертный,",0,272,0,0],["v","Я раню, коль не спрячется… Эй, там!",0,273,0,0],["v","Не слышите? Что? Каково? Ага!",0,274,0,0],["v","Что ж медлите? Туда летите, выше,",0,275,0,0],["v","Крылатые, свищите Фебу в уши!",0,276,0,0],["sd","Припадок безумия падает: у <span class=\"ch\" data-ch=\"orest\">Ореста</span> опускаются руки, глаза точно открываются, он проводит рукой по лицу и, остановившись, с минуту молчит. <span class=\"ch\" data-ch=\"elektra\">Электра</span>, которая сквозь слезы все время тревожно следила за развитием его бреда, теперь закрыла голову и плачет."],["v","Га! Зачем я здесь?.. Я брежу, задыхаюсь,",0,277,0,0],["v","С постели убежал… А волн уж нет",0,278,0,0],["v","Передо мной… Опять спокойно море…",0,279,0,0],["sd","(Оборачивается и видит <span class=\"ch\" data-ch=\"elektra\">Электру</span>.)"],["v","Сестра, зачем ты там лицо себе",0,280,0,1],["v","Закрыла? Или плачешь? О Электра,",0,280,0,0],["v","Как стыдно мне: заставил я недуга",0,281,0,0],["v","Тебя нести со мною иго, деву!..",0,282,0,0],["v","Ужели плеч <span class=\"ch\" data-ch=\"orest\">Ореста</span> мало?.. Да,",0,283,0,0],["v","Ты одобряла брата, но убийство",0,284,0,0],["v","Я совершил один. И упрекать",0,285,0,0],["v","<span class=\"ch\" data-ch=\"elektra\">Электру</span> невозможно. Феб <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,285,0,0],["v","Подвигнул на несчастье, а теперь",0,286,0,0],["v","Он на словах его лишь ободряет…",0,287,0,0],["v","О, если бы хоть тень отца спросить",0,288,0,0],["v","Мне удалось тогда, перед убийством,",0,289,0,0],["v","Наверное, касался с мольбой",0,290,0,1],["v","До бороды моей, отец убитый",0,290,0,0],["v","Заворожил бы дерзновенный нож.",0,291,0,0],["v","Еще когда бы местью мог я солнце",0,292,0,0],["v","Ему вернуть… А то так много бед,",0,293,0,0],["v","Так много мук — и даром… Ну, родная,",0,294,0,0],["v","Откройся же и плакать перестань.",0,295,0,0],["v","Сам знаю я, что тяжело. Покуда",0,295,0,0],["v","В отчаянье и ужасе слабел",0,296,0,0],["v","Смущенный ум <span class=\"ch\" data-ch=\"orest\">Ореста</span>, лаской нежной",0,297,0,0],["v","Ты утешать его старалась. Но пришел",0,298,0,0],["v","И твой черед — ты плачешь… О печальной",0,299,0,0],["v","Подумать дай и брату… Перейди",0,300,0,1],["v","На время в дом — пора согнать дремоту",0,300,0,0],["v","С усталых вежд, набраться новых сил",0,301,0,0],["v","И ванною отрадной освежиться;",0,302,0,0],["v","Ведь, о больном заботясь, и самой",0,303,0,0],["v","Не диво занемочь; подумай только,",0,304,0,0],["v","Что сталось бы с обоими? И мне",0,305,0,0],["v","Оставь, сестра, последнюю опору.",0,306,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","с живостью и открыв лицо"],["v","О да, о да, с тобою жить, с тобой",0,307,0,0],["v","И умереть! Да если бы убили",0,308,0,0],["v","Ореста, где же мне одной спастись?",0,309,0,0],["v","Ни брата, ни отца, ни друга. Мне ты",0,310,0,1],["v","Велишь идти, Орест, а сам ложись",0,310,0,0],["v","И, ужасам да призракам не веря,",0,311,0,0],["v","Не покидай одра. Вообразишь, —",0,312,0,0],["v","Так и здоров, да все равно что болен:",0,313,0,0],["v","Измучится, волнуясь, человек.",0,314,0,0],["sd","(Уходит в дом.)"],["v","<span class=\"ch\" data-ch=\"orest\">Орест</span> ложится и засыпает.",0,315,0,0],["scene","Первый музыкальный антракт","s7",2,7],["sp","Хор"],["str","Строфа"],["v","О, горе мне!",0,316,2,0],["v","Бурноногие и крылатые,",0,317,0,0],["v","О богини! О властные!",0,318,0,0],["v","Чей слезами обвеянный",0,319,0,0],["v","Рой косматый безрадостен…",0,320,0,1],["v","Темнокожие девы мщения,",0,320,0,0],["v","Распустили вы крылья по воздуху, —",0,321,0,0],["v","Незамытой все крови ищете, —",0,322,0,0],["v","За убийцей вослед вы прянули.",0,323,0,0],["v","Умоляю вас! Умоляю вас!",0,324,0,0],["v","Агамемнона",0,325,0,0],["v","Пусть отдышится от безумья сын!",0,326,0,0],["v","Сколько мук, увы! И каких, Орест,",0,327,0,0],["v","Налегло на тебя с тех пор,",0,328,0,0],["v","Как с треножника павшее слово",0,329,0,0],["v","Гулкий пол воротил тебе",0,330,0,1],["v","В тишине срединного храма.",0,330,0,0],["str","Антистрофа"],["v","О, Зевс, о, Зевс!",0,331,2,0],["v","Грусть берет глядеть, как на бойню там",0,332,0,0],["v","Заманили несчастного.",0,333,0,0],["v","Дразнит бог его кровию,",0,334,0,0],["v","Призрак матери в дом за ним ведет.",0,335,0,0],["v","Материнская душит сына кровь:",0,335,0,0],["v","Этим призраком демон в груди немой",0,336,0,0],["v","Скопит слез ему тучу тяжкую…",0,337,0,0],["v","Милосердие! Милосердие!",0,338,0,0],["v","Между смертными",0,339,0,0],["v","Нет великого счастья прочного:",0,340,0,1],["v","Демон тот, что рвет паруса ладьи,",0,341,0,0],["v","В бездне горестей топит счастье,",0,342,0,0],["v","Как в волнах ненасытно злых…",0,343,0,0],["v","О, кого же почту я песней,",0,344,0,0],["v","Коль не Тантала славный дом?",0,345,0,0],["v","Он наследье браков небесных.<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,346,0,0],["str","Эпод"],["v","Властелин <span class=\"ch\" data-ch=\"menelay\">Менелай</span> приближается:",0,347,0,0],["v","Поглядеть на него — сколько неги в нем.",0,350,0,1],["v","Танталидова кровь царей видна.",0,350,0,0],["sd","Со стороны противоположной той, с которой пришел хор, показывается <span class=\"ch\" data-ch=\"menelay\">Менелай</span> со свитой."],["v","О, привет тебе! Ты от нас, Атрид,",0,351,0,0],["v","Корабли увел целой тысячей",0,352,0,0],["v","К брегу Азии.",0,353,2,0],["v","Сколько счастия у тебя в лице!",0,353,0,0],["v","Так и светится: от богов теперь",0,354,0,0],["v","Все получено.",0,355,2,0],["act","Действие второе","a3","II"],["scene","Явление шестое","s8",3,8],["sd","<span class=\"ch\" data-ch=\"menelay\">Менелай</span> и <span class=\"ch\" data-ch=\"orest\">Орест</span> (который просыпается во время последних слов <span class=\"ch\" data-ch=\"menelay\">Менелая</span>)."],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Вот и чертог… И радостно его",0,356,0,0],["v","Увидеть мне, взамен высокой Трои.",0,356,0,0],["v","И плачу я, когда в душе помыслю,",0,357,0,0],["v","Какою тучей бед его очаг",0,358,0,0],["v","Окутан, — да, черней я и не видел!",0,359,0,0],["sd","Пауза."],["v","Злосчастие и смерть Агамемнона",0,360,0,1],["v","И грех жены впервые я узнал,",0,360,0,0],["v","К Малее подплывая: из пучины",0,361,0,0],["v","Нереевых вещаний толкователь",0,362,0,0],["v","И сам неложный бог передо мной",0,363,0,0],["v","Предстал, и различил я голос Главка:<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,364,0,0],["v","\"О Менелай! Твой бездыханен брат —",0,365,0,0],["v","Над ванною женою он зарезан\".",0,365,0,0],["v","Сказал и сердце мне исполнил слез,",0,366,0,0],["v","И плакали товарищи похода",0,367,0,0],["v","Вокруг меня.",0,368,0,0],["v","Потом, когда земли",1,368,0,0],["v","Коснулся я и уж сюда <span class=\"ch\" data-ch=\"elena\">Елена</span>",0,369,0,0],["v","Из Навплии сбиралась плыть, а я",0,370,0,1],["v","Душой горел скорей обнять <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,370,0,0],["v","И мать его счастливую обнять,",0,371,0,0],["v","От здешнего я слышу морехода,",0,372,0,0],["v","Что нечестивою рукою сын",0,373,0,0],["v","Зарезал дочь <span class=\"ch\" data-ch=\"tindar\">Тиндара</span>.",0,374,0,0],["sd","(К хору.)"],["v","Вы, юницы,",0,375,4,0],["v","Скажите мне — а где ж теперь <span class=\"ch\" data-ch=\"orest\">Орест</span>,",0,376,0,0],["v","Злодей и дерзостный? Когда отсюда",0,377,0,0],["v","Я уезжал под Трою, он дитя",0,378,0,0],["v","Был малое. Теперь и не узнать бы.",0,379,0,0],["sd","Во время последних слов <span class=\"ch\" data-ch=\"menelay\">Менелая</span> <span class=\"ch\" data-ch=\"orest\">Орест</span> бесшумно поднимается с ложа, которого раньше <span class=\"ch\" data-ch=\"menelay\">Менелай</span> не замечал. Но вот <span class=\"ch\" data-ch=\"menelay\">Менелай</span> случайно обернулся и встречается глазами с <span class=\"ch\" data-ch=\"orest\">Орестом</span>. Пауза, во время которой, узнавая друг друга, они молча смотрят один на другого; контраст разителен: немытый, растрепанный <span class=\"ch\" data-ch=\"orest\">Орест</span> и сияющий, нарядный <span class=\"ch\" data-ch=\"menelay\">Менелай</span>, в котором, однако, самодовольная уверенность смягчена набежавшим облаком нежной грусти."],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Царь, вот — Орест… Коль ты искал его,",0,380,0,1],["v","Печальную он сам расскажет повесть.",0,380,0,0],["sd","(Сходит с постели и приближается к <span class=\"ch\" data-ch=\"menelay\">Менелаю</span>, который инстинктивно отступает на шаг, не столько из страха, сколько из брезгливости.)"],["v","Но прежде дай колен твоих с мольбой",0,381,0,0],["v","Коснуться мне… с мольбой, и первой в жизни…",0,382,0,0],["v","Молящих мне не надо ветви… О,",0,383,0,0],["v","Спаси меня, погрязшего в страданьях…",0,384,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","О, кто же ты? Подземных стран жилец?",0,385,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты прав: я труп, под солнцем позабытый.",0,386,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Твоих волос косматых страшен вид…",0,387,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не вид — душа меня, душа порочит!<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,388,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","И воспаленный твой ужасен взгляд!..",0,389,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да, — в чем душа, а имя остается…",0,390,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","И имени-то нет для дикаря.",0,391,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","тихо"],["v","Есть имя — «матереубийца» имя.",0,392,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Не повторяй напрасно тяжких слов.",0,393,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Сам демон их в <span class=\"ch\" data-ch=\"orest\">Оресте</span> повторяет…",0,394,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но что с тобой? Какой недуг томит?",0,395,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Его зовут и у злодеев — совесть.<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,396,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Слова темны — лишь ясное умно.",0,397,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Скажу ясней: тоска меня снедает…",0,398,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Да, грозный бог… но лечат и тоску…",0,399,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","продолжая"],["v","Безумием кровь матери карает.",0,400,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","А как давно? Который день пошел?",0,401,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","С тех пор как ей могилу стали сыпать.",0,402,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Что ж, дома началось иль у костра?",0,403,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Пока я ждал, чтоб тело стало пеплом.",0,404,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Пособник был в убийстве у тебя?",0,405,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","<span class=\"ch\" data-ch=\"pilad\">Пилад</span> со мной в товарищах работал.",0,406,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","помолчав"],["v","Что ж видишь ты в своих недужных снах?",0,407,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","тихо"],["v","Я вижу трех богинь, подобных ночи.",0,408,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Их называть излишнее, <span class=\"ch\" data-ch=\"orest\">Орест</span>.",0,409,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Приличие и страх язык сковали.",0,410,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Чрез них тебя кровь матери пьянит.",0,410,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","закрывая лицо руками"],["v","О, как они меня, гоняя, мучат…",0,411,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Иль диво зло терпеть творящим зло?",0,412,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но бедствия всегда сложить я властен…",0,413,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Убив себя?.. Иль это так умно?",0,414,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нет, я могу вину сложить на Феба:",0,415,0,0],["v","Мне Феб убить родимую велел.",0,416,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Он позабыл, что есть на свете правда?",0,417,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Бог все же бог, а мы — его рабы.",0,418,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","И тот же Феб дает <span class=\"ch\" data-ch=\"orest\">Оресту</span> гибнуть?",0,419,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Все медлит он. Бессмертных нрав таков.",0,420,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","А сколько дней, как умерла царица?",0,421,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Шестой идет. Костер еще горяч…",0,422,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Торопятся ж бессмертные расплатой.",0,423,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я не речист, но верный друг отцу.",0,424,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","А самому была ли другу польза?",0,425,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Покуда нет. А медленность — зарез.",0,426,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","помолчав"],["v","Как с городом дела после убийства?",0,427,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я отлучен. Со мной не говорят.",0,428,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","И не был ты очищен, по обряду?",0,429,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Передо мной все двери заперты.",0,430,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но твоего кто ж требует изгнанья?",0,431,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Здесь есть Эак, старинный враг отца.<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,432,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Он это мстит тебе за Паламеда.",0,433,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я — ни при чем и жертва трех врагов.",0,434,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","А кто ж еще? Друзья Эгисфа, верно?",0,435,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да, их черед кичиться надо мной.",0,436,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Так трон отца не передан <span class=\"ch\" data-ch=\"orest\">Оресту</span>?",0,437,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Кто ж царство даст? — мне жизни не дают.",0,438,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но как и чем? Скажи, коль можешь, толком.",0,439,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Сегодня суд над нами черепков…<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,440,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Решит: изгнать, казнить иль дать свободу?",0,441,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нет: камнями побить иль не побить.",0,442,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Ну, а побег? Перемахнуть границу…",0,443,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Щиты вокруг, и медь со всех сторон.",0,444,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Твоих врагов или аргосской рати?",0,445,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Весь <em>город</em>, царь, <span class=\"ch\" data-ch=\"orest\">Ореста</span> казни ждет.",0,446,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Да, подошло тебе, несчастный, туго.",0,447,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","И вся моя надежда на тебя.",0,448,0,0],["v","Меж горькими, сияя счастьем, царь,",0,449,0,0],["v","Не откажи с друзьями поделиться",0,450,0,1],["v","Избытками удачи, а в обмен",0,450,0,0],["v","Трудов себе возьми и муки долю.",0,451,0,0],["v","Не будь же скуп и нам отцовский долг",0,452,0,0],["v","Уплачивай, подавленным нуждою.",0,453,0,0],["v","Не правда ли: те призрачны друзья,",0,454,0,0],["v","Которые в несчастье друга бросят?",0,455,0,0],["sp","Корифей"],["v","Но старческой стопой сюда спешит",0,456,0,0],["v","Сам царь <span class=\"ch\" data-ch=\"tindar\">Тиндар</span>. Спартанец — в ризе черной,",0,457,0,0],["v","В знак траура по дочери обрит.",0,458,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О Менелай, я гибну. Что за ужас,",0,459,0,0],["v","После того, что сделал я, глядеть",0,460,0,1],["v","На старика: меня вскормил он, внука",0,461,0,0],["v","Он целовал, я помню, на руках",0,462,0,0],["v","Меня носил, и, право, Диоскуров",0,463,0,0],["v","Любили меньше Леда и <span class=\"ch\" data-ch=\"tindar\">Тиндар</span>…",0,464,0,0],["v","И вот, и вот… о, горе сердцу внука!",0,465,0,0],["v","Чем за любовь я деду заплатил!",0,466,0,0],["v","Лицо горит стыдом, а скрыться негде…",0,467,0,0],["v","И тучей бы завесил я глаза…",0,468,0,0],["scene","Явление седьмое","s9",3,9],["sd","Те же и <span class=\"ch\" data-ch=\"tindar\">Тиндар</span> (с домашней стороны). Он в трауре и обрит. Сопровождающая его свита также. Вначале он не замечает ни <span class=\"ch\" data-ch=\"orest\">Ореста</span>, который отошел в сторону, ни даже <span class=\"ch\" data-ch=\"menelay\">Менелая</span>."],["sp","<span class=\"ch\" data-ch=\"tindar\">Тиндар</span>"],["v","Скажите: где же он, наш царский зять?",0,470,0,1],["v","Где <span class=\"ch\" data-ch=\"menelay\">Менелай</span>? У гроба Клитемнестры",0,470,0,0],["v","Мольбы творя с священным возлияньем,",0,471,0,0],["v","Услышал я, что здесь он и с женой",0,472,0,0],["v","И невредим… Да, сколько лет разлуки!..",0,473,0,0],["v","Но где же он?.. Ему, направо став,<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,473,0,0],["v","Хочу сказать, что свидеться не чаял",0,474,0,0],["v","И что обнять его отрадно мне.",0,475,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Привет тебе, чье ложе зрело Зевса.",0,476,0,0],["sp","<span class=\"ch\" data-ch=\"tindar\">Тиндар</span>"],["v","Тебе привет от тестя, <span class=\"ch\" data-ch=\"menelay\">Менелай</span>.",0,476,0,0],["sd","(Хочет подойти, но замечает <span class=\"ch\" data-ch=\"orest\">Ореста</span> и в ужасе отступает.)"],["v","Га… Нам не дано предвидеть бед… А жаль…",0,477,0,0],["v","Змееныша и матереубийцу",0,478,0,0],["v","Я нахожу перед дворцом — и блеск",0,479,0,0],["v","Недужных глаз в груди вздымает злобу.",0,480,0,1],["v","Беседуешь с нечистым, Менелай?",0,481,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Его отец был близок мне… Что хочешь?",0,482,0,0],["sp","<span class=\"ch\" data-ch=\"tindar\">Тиндар</span>"],["v","С такой душой Агамемнонов сын!",0,483,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Иль не почтить отца в несчастном сыне?",0,484,0,0],["sp","<span class=\"ch\" data-ch=\"tindar\">Тиндар</span>"],["v","Меж варваров ты им подобен стал.<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,485,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Так уж родных теперь не чтут в Элладе?",0,486,0,0],["sp","<span class=\"ch\" data-ch=\"tindar\">Тиндар</span>"],["v","Законы чтут и чтить велят у нас.",0,487,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Для мудреца все, что <em>велят</em>, — оковы.",0,488,0,0],["sp","<span class=\"ch\" data-ch=\"tindar\">Тиндар</span>"],["v","Будь мудрецом тогда, я не мудрец…",0,489,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Да, старца гнев едва ли умудряет…",0,490,0,1],["sp","<span class=\"ch\" data-ch=\"tindar\">Тиндар</span>"],["dir","сдержанно"],["v","Возможен спор о мудрости, но спор,",0,490,0,0],["v","Умен ли был <span class=\"ch\" data-ch=\"orest\">Орест</span>, едва ль возможен;",0,491,0,0],["v","Коль белое всем бело и черно",0,492,0,0],["v","Всем черное, безумней, верно,",0,493,0,0],["v","На свете не найдется. Он признать",0,494,0,0],["v","Всем эллинам священного закона",0,495,0,0],["v","Не захотел; когда отец его",0,496,0,0],["v","Дух испустил, ударом пораженный",0,497,0,0],["v","Гнуснейшим, — да, всегда скажу: удар,",0,498,0,0],["v","Что дочь моя замыслила, был гнусен;",0,499,0,0],["v","Преследуй мать законом и тотчас",0,500,0,1],["v","Вон вышвырни ее, — и из несчастья",0,500,0,0],["v","Он вышел бы прославленный за ум,",0,501,0,0],["v","Закону страж и друг благочестивым…",0,502,0,0],["v","А он что делает? На тот же путь",0,503,0,0],["v","Греха идет и, мигом забывая",0,504,0,0],["v","Свой сан судьи, — убийцей, палачом",0,505,0,0],["v","Становится, презреннее убитой.",0,506,0,0],["v","Ну, сам скажи мне, Менелай, положим,",0,507,0,0],["sd","(указывает на <span class=\"ch\" data-ch=\"orest\">Ореста</span>)"],["v","Что и его жена убьет, потом",0,508,0,0],["v","Сын отомстит и мать уложит мертвой,",0,509,0,0],["v","От сына сын — и снова кровь и смерть…",0,510,0,1],["v","Да где ж конец кровавой этой цепи?",0,510,0,0],["v","Нет, хорошо придумали отцы:",0,511,0,0],["v","Коль человек запятнан кровью, встречи",0,512,0,0],["v","Он должен избегать и не позорить",0,513,0,0],["v","Согражданам глаза, сначала пусть",0,514,0,0],["v","Очистится изгнаньем… Но убийцы",0,515,0,0],["v","Не убивай. Иначе загрязнен",0,516,0,0],["v","Всегда один последний мститель будет.",0,517,0,0],["v","Безбожных жен не защищаю я",0,518,0,0],["v","И первый Клитемнестру ненавижу,",0,519,0,0],["v","Не меньше и <span class=\"ch\" data-ch=\"elena\">Елену</span>, — ей из уст",0,520,0,1],["v","Привета не слыхать отцовских, нет!",0,520,0,0],["v","Да и тебе похвал моих напрасно",0,521,0,0],["v","За твой поход троянский ожидать.",0,522,0,0],["v","И все-таки, поколе сил хватает,",0,523,0,0],["v","Я буду за закон стоять, я буду",0,524,0,0],["v","Искоренять позорнейший обычай",0,525,0,0],["v","И пагубный для граждан и земли.<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,525,0,0],["sd","(<span class=\"ch\" data-ch=\"orest\">Оресту</span>.)"],["v","Что должен был ты пережить, несчастный,",0,526,0,0],["v","Когда тебя, освобождая грудь,<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,527,0,0],["v","Молила мать, коль я, старик, не бывший",0,528,0,0],["v","Свидетелем, помыслю — и заплачу.",0,529,0,0],["sd","(Плачет.)"],["v","Вот и слова мои уже сбылись:",0,530,0,1],["v","Безумием и страхом, ненавистный,",0,531,0,0],["v","За мать ты платишь…",0,532,0,0],["v","Или мне",1,532,0,0],["v","Свидетелей тут нужно? Сам не вижу?",0,533,0,0],["sd","(<span class=\"ch\" data-ch=\"menelay\">Менелаю</span>.)"],["v","Ты, царь и зять, ему не помогай,",0,534,0,0],["v","Коль ссоры сам с бессмертными не хочешь,",0,535,0,0],["v","Пускай его каменьями побьют,",0,536,0,0],["v","Или тебе не видеть больше Спарты.",0,537,0,0],["v","О, дочь моя была достойна казни,",0,538,0,0],["v","Но разве от <span class=\"ch\" data-ch=\"orest\">Ореста</span>? Да, во всем",0,539,0,0],["v","Я, кажется, был счастлив, нужно ж было,",0,540,0,1],["v","Чтобы таких родил я дочерей!",0,541,0,0],["sp","Корифей"],["v","Тот зависти достоин, кто детьми",0,542,0,0],["v","Прославлен был, бед не познавши громких.",0,543,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Мне говорить с тобою, старец, жутко:",0,544,0,0],["v","Ведь свежих ран, сердечных ран твоих",0,545,0,0],["v","Касаться речь моя должна невольно.",0,546,0,0],["v","Ты с поприща позволь мне хоть года",0,548,0,1],["v","Твои убрать: смущен я сединою.",0,550,0,1],["v","Ты говоришь: я грешен был, старик,",0,546,0,1],["v","Что мать свою убил, слова другие",0,546,0,0],["v","И ту же мысль возьми, и буду прав:",0,547,0,1],["v","Без мщения отца я не оставил.",0,548,0,0],["v","Мне выбор был судьбой определен:",0,551,0,1],["v","Между отцом засеявшим и нивой,",0,551,0,0],["v","Иль дочерью твоей, — со стороны",0,552,0,0],["v","Приявшею зародыш и ведущим",0,553,0,0],["v","Род от семян. Я предпочел отца<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,554,0,0],["v","И честь его — груди, меня вспоившей.",0,555,0,0],["v","Да, дочь твоя — я матерью боюсь",0,556,0,0],["v","Ее назвать, — в безумном самоволье",0,557,0,0],["v","Затеяв брак, на ложе перешла…",0,558,0,0],["v","К иным мужьям, — хоть я отлично знаю,",0,559,0,0],["v","Что сам себя порочу, приговор",0,560,0,1],["v","Читая ей, но не смолчу: к Эгисфу.",0,560,0,0],["v","Он тайный ей в чертоге был супруг.",0,561,0,0],["v","Я, труп его покрывши материнским,",0,562,0,0],["v","Нечестие свершил… Что делать?.. Месть",0,562,0,0],["v","То за отца была.",0,563,0,0],["v","Вот ты о казни",1,563,0,0],["v","Моей твердишь с угрозами, — дивлюсь",0,564,0,0],["v","Тебе, старик: мне кажется, Эллада",0,565,0,0],["v","Благословлять должна бы подвиг мой.",0,565,0,0],["v","Их попусти… Пусть только состраданье",0,566,0,0],["v","Удастся им искусно уловить,",0,567,0,0],["v","Перед детьми свои открывши груди, —",0,567,0,0],["v","Убийцам этим, — а потом предлог",0,568,0,0],["v","Для замысла кровавого придумать",0,569,0,0],["v","Уж нипочем. Я сделал ужас, да!",0,570,0,1],["v","Но я прижег гангрену, злой обычай…",0,570,0,0],["v","Не потерпев и мать не пощадив,",0,571,0,0],["v","Я поступил законно.",0,572,0,0],["v","Ты подумай,",1,572,0,0],["v","Над кем она глумилась? Ратоборцу",0,573,0,0],["v","За Грецию и ложе осквернить!",0,574,0,0],["v","Вину поняв свою, не захотела ж<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,575,0,0],["v","Виновную небось она убить.",0,576,0,0],["v","Нет, моего она отца казнила…",0,577,0,0],["v","Ради богов — коли прилично их",0,578,0,0],["v","Тут поминать, — а если б, разбирая",0,579,0,0],["v","Процесс, молчать о ней я предпочел,",0,580,0,1],["v","Убийцу-мать безмолвием одобрив, —",0,580,0,0],["v","Иль думаешь, разгневанный отец",0,581,0,0],["v","Эриний бы на сына не воздвигнул?",0,582,0,0],["v","Иль матери союзницы одной",0,582,0,0],["v","Эринии, а не тому, кто гнусно,",0,583,0,0],["v","Предательски убит?",0,584,0,0],["v","А знаешь, старец,",1,584,0,0],["v","Что это ты один меня сгубил,",0,585,0,0],["v","Порочною родивши Клитемнестру:",0,585,0,0],["v","Иль был бы я без этой злой жены",0,586,0,0],["v","И сиротой и матереубийцей?..",0,587,0,0],["v","И Одиссей женатым уплывал,",0,587,0,0],["v","Но нового не заводила мужа",0,588,0,0],["v","Жена его и ложе берегла,",0,589,0,0],["v","И Телемах не тронул Пенелопы.",0,590,0,1],["v","Нет, старец, нет, — чьим троном пуп земной<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,590,0,0],["v","Покрыт, того зовите нечестивым,",0,591,0,0],["v","А не меня. За Феба не ответчик,",0,592,0,0],["v","Я слов его ослушаться не смел.",0,593,0,0],["v","Или уж бог для вас так маловажен,",0,594,0,0],["v","Что ссылкою на Фебовы слова",0,595,0,0],["v","И скверны смыть с себя мне не удастся?",0,596,0,0],["v","Коль он теперь <span class=\"ch\" data-ch=\"orest\">Ореста</span> не спасет,",0,597,0,0],["v","Сам натолкнув его на это дело,",0,598,0,0],["v","То для людей вообще спасенья нет.",0,599,0,0],["v","А ты, старик, не говори, что дурно",0,600,0,1],["v","Поступлено. «Не удалось», — скажи.",0,600,0,0],["v","Не только ль те, что женятся удачно,",0,601,0,0],["v","И счастливы? А не задался брак —",0,602,0,0],["v","И меж чужих и дома ты несчастлив.",0,603,0,0],["sp","Корифей"],["v","Да, женщины помеха, и мужья",0,604,0,0],["v","Чрез них еще средь бед своих несчастней.",0,605,0,0],["sp","<span class=\"ch\" data-ch=\"tindar\">Тиндар</span>"],["dir","<span class=\"ch\" data-ch=\"orest\">Оресту</span>"],["v","Пока безумной дерзостью слова",0,606,0,0],["v","Ты уснащал ответные, чтоб сердцем",0,607,0,0],["v","Я восскорбел, — во мне одно разжег",0,608,0,0],["v","Желанье ты — твоей скорейшей казни.",0,609,0,0],["v","Пусть этот дар прибавочный теперь",0,610,0,1],["v","Дочернюю могилу украшает.",0,610,0,0],["v","На сходку я к аргосцам поспешу",0,611,0,0],["v","И, хочет ли или не хочет, город",0,612,0,0],["v","Расшевелю, заставлю их тебя",0,613,0,0],["v","Каменьями побить с <span class=\"ch\" data-ch=\"elektra\">Электрой</span> вместе.",0,614,0,0],["v","Ее особенно. Тебя на мать",0,615,0,0],["v","Кто натравлял? кто небылицы вечно",0,615,0,0],["v","Нашептывал? кто раздувал вражду?",0,616,0,0],["v","Иль не она про сны, что Агамемнон",0,617,0,0],["v","Жене послал, поведала тебе?",0,618,0,0],["v","Про тайный брак с Эгисфом рассказала?",0,619,0,0],["v","О, этот брак! Да встретит под землей",0,620,0,1],["v","Его вражда бессмертных: ненавистен",0,620,0,0],["v","Он был и здесь, Атридов дом объяв",0,621,0,0],["v","Иным огнем, не пламенем Гефеста.",0,622,0,0],["sd","(К <span class=\"ch\" data-ch=\"menelay\">Менелаю</span> резко.)"],["v","Тебе ж мой сказ последний, <span class=\"ch\" data-ch=\"menelay\">Менелай</span>.",0,622,0,0],["v","Коли свойство со мной и гнев <span class=\"ch\" data-ch=\"tindar\">Тиндара</span>",0,623,0,0],["v","Во что-нибудь ты ценишь, то убийц",0,624,0,0],["v","Наперекор богам не будешь больше",0,625,0,0],["v","Оборонять. Пусть казнь их совершится!",0,625,0,0],["v","Иль о земле Спартанской позабудь.",0,626,0,0],["v","Сообразив все это, верно, грешных",0,627,0,0],["v","Для праведных покинешь ты друзей.",0,627,0,0],["sd","(Слугам.)"],["v","Прислужники… я кончил… уводите…",0,628,0,0],["sd","Передает жезл и уходит со слугами и свитой."],["scene","Явление восьмое","s10",3,10],["v","Те же, без <span class=\"ch\" data-ch=\"tindar\">Тиндара</span> и свиты.",0,629,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ступай! Теперь помехой седина",0,630,0,1],["v","Не будет нам, и мы начнем беседу…",0,630,0,0],["sd","(К <span class=\"ch\" data-ch=\"menelay\">Менелаю</span>, который, начиная с последней паузы <span class=\"ch\" data-ch=\"tindar\">Тиндара</span>, обнаруживает замешательство и волнение.)"],["v","Что кружишь ты в раздумье, Менелай,",0,631,0,0],["v","Или, двоясь, в тебе и мысли кружат?",0,632,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Не говори… Ума не приложу…",0,633,0,0],["v","С чего начать? Откуда ждать удачи?",0,634,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не принимай решения, пока",0,635,0,0],["v","Меня не выслушал — еще успеешь.",0,636,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Я слушаю. Да, есть минуты, — слов",0,637,0,0],["v","Безмолвие надежнее, порою ж",0,638,0,0],["v","Молчать нельзя, слова необходимы.",0,639,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Тут коротко не скажешь, но речей",0,640,0,1],["v","Не бойся длинных, царь, — их легче слушать.",0,640,0,0],["v","Мне твоего не надо, Менелай!",0,641,0,0],["v","Отцовское отдай, отцу ты должен.",0,642,0,0],["v","<span class=\"ch\" data-ch=\"menelay\">Менелай</span> делает движение рукой и отстраняется.",0,643,0,0],["v","Не деньги, нет, дороже денег — жизнь.",0,644,2,0],["v","Спаси нам жизнь… нет выше достоянья…",0,645,2,0],["v","Пусть я не прав. Не бойся ж злом и ты",0,645,2,0],["v","Страданье возместить. Да разве правдой",0,646,2,0],["v","Агамемнон в Элладе рать собрав,",0,647,2,0],["v","Ее повел под Илион — иль промах",0,648,2,0],["v","Заглаживал он собственный, когда",0,649,2,0],["v","Насилием залечивал <span class=\"ch\" data-ch=\"elena\">Елены</span>,",0,650,2,1],["v","Твоей жены, недуг! Или себя",0,651,2,0],["v","Жалел, когда копьем для <span class=\"ch\" data-ch=\"menelay\">Менелая</span>",0,652,2,0],["v","Он отбивал жену? Пора, отдай",0,653,2,0],["v","Нам старый долг и тою же монетой,",0,654,2,0],["v","За десять лет работы <em>день один</em>",0,655,2,0],["v","Мы просим, <em>день один</em> твоей защиты.",0,656,2,0],["v","Сестру под нож Авлида обрекла —",0,657,2,0],["v","Пусть за тобой. Ты можешь Гермионы",0,658,2,0],["v","Не убивать — коль человек нуждой",0,659,2,0],["v","Придавлен, как <span class=\"ch\" data-ch=\"orest\">Орест</span>, то на уступки",0,660,2,1],["v","Всегда пойдет.",0,661,2,0],["v","Но бедному отцу",1,661,0,0],["v","За все труды ты возвратить обязан",0,662,2,0],["v","<span class=\"ch\" data-ch=\"orest\">Ореста</span> жизнь и дочь его спасти.",0,663,2,0],["v","Иль хочешь ты, чтобы со мной угас",0,664,2,0],["v","Отцовский дом? Иль скажешь: «невозможно»?",0,665,2,0],["v","Тогда на что ж и друг? Среди удач",0,666,2,0],["v","Благожеланий бога нам довольно,",0,667,2,0],["v","Друг нужен нам в несчастье.",0,668,2,0],["v","Говорят,",1,668,0,0],["v","Что ты <span class=\"ch\" data-ch=\"elena\">Елену</span> любишь — этим чувствам",0,669,2,0],["v","Мне стыдно льстить, но именем жены",0,670,3,1],["v","Тебя молю —",0,670,2,0],["sd","(касается его колен, потом в сторону, с горечью)"],["v","о, до чего бедою",0,671,4,0],["v","Принижен я, из-за чего тружусь?",0,672,2,0],["sd","(Пауза. Поднимая голову.)"],["v","Не за себя молю, за дом отцовский.",0,673,2,0],["v","Ведь братья вы… Ты вспомни, что теперь",0,674,2,0],["v","Хоть под землею брат твой, но над нами",0,675,2,0],["v","Парит душа его и слышит нас,",0,675,2,0],["v","Слова мои беззвучно повторяя.",0,676,2,0],["v","О царь, из рук стенаний, слез и бед",0,677,2,0],["v","Прияв фиал, отдай мне чашу жизни.",0,678,2,0],["v","О, сколько уст к ней тянется со мной.",0,679,2,0],["sp","Корифей"],["v","К несчастному, — хоть женщина, а все же",0,680,0,1],["v","Молю, — склонись: могуч ты, господин.",0,681,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Мне голова твоя, Орест, священна,",0,682,0,0],["v","От мук спасать тебя мой сладкий долг.",0,683,0,0],["v","О, человек, коль боги силу дали",0,684,0,0],["v","Ему, семье обязан помогать.",0,685,0,0],["v","Рискуя сам, ее врагов он должен",0,686,0,0],["v","Уничтожать. Но разве точно сила",0,687,0,0],["v","От бога мне дана? Союзных войск",0,688,0,0],["v","Со мною нет — из тысячи блужданий",0,689,0,0],["v","Сберег я горсть ничтожную друзей,",0,690,0,1],["v","И хочешь ты, чтобы Пеласгов Аргос",0,691,0,0],["v","В открытом я сраженье победил.",0,692,0,0],["v","Поговорить — вот все, что мне надежду",0,693,0,0],["v","Еще дает. А с малыми преград,",0,694,0,0],["v","Как ни трудись, ты силами великих",0,695,0,0],["v","Не одолеешь — детские мечты!",0,696,0,0],["v","Когда народ от гнева разъярится,",0,697,0,0],["v","Он как пожар — тушить не помышляй!",0,698,0,0],["v","Но если, уступив, сумеешь выждать,",0,699,0,0],["v","Чтоб ярость он всю выдохнул, тогда",0,700,0,1],["v","Мгновенья не теряй и можешь тотчас",0,700,0,0],["v","С народа взять что хочешь без труда.",0,701,0,0],["v","И жалость в нем, и гнев живет великий,",0,702,0,0],["v","Терпение имей — и ты спасен.",0,703,0,0],["v","С <span class=\"ch\" data-ch=\"tindar\">Тиндаром</span> я поговорю, — быть может,",0,703,0,0],["v","Слепую страсть Орестовых врагов",0,704,0,0],["v","Удастся нам склонить в его же пользу.",0,705,0,0],["v","Коль чересчур ты натянул канат",0,706,0,0],["v","От паруса, ладья твоя затонет,",0,706,0,0],["v","Ослабь его — поднимется… Ни бог",0,707,0,0],["v","Горячности излишней не потерпит,",0,708,0,0],["v","Ни граждане. Мой долг спасать тебя,",0,709,0,0],["v","Согласен я, — но не открытой силой,",0,710,0,1],["v","А ловкостью… Оружием, борьбой",0,711,0,0],["v","Мне не отбить тебя, копье не сможет",0,712,0,0],["v","Одно трофей над грудой стольких бед",0,713,0,0],["v","Установить. Иначе я не стал бы",0,714,0,0],["v","Тут с Аргосом любезничать. Увы!",0,715,0,0],["v","И мудрый — раб судьбы, коль это нужно.",0,716,0,0],["sd","(Уходит поспешно, не оглядываясь на <span class=\"ch\" data-ch=\"orest\">Ореста</span>, за ним свита.)"],["scene","Явление девятое","s11",3,11],["sd","<span class=\"ch\" data-ch=\"orest\">Орест</span> один (смотря вслед <span class=\"ch\" data-ch=\"menelay\">Менелаю</span>, с горечью)"],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Прославленный походом за женой,",0,717,0,0],["v","Ничто как царь, а сердцем трус негодный,",0,718,0,0],["v","Друзей в беде покинув, ты бежишь!",0,719,0,0],["v","Увы! Увы! Благодеянья брата",0,720,0,1],["v","Ты свел на нет. О мой отец, друзей",0,720,0,0],["v","Надежных нет с тобой! С его уходом",0,721,0,0],["v","Последний луч надежды догорел,",0,722,0,0],["v","И от врагов твой род не отобьется.",0,723,0,0],["sd","Пауза."],["sd","(Пристально смотрит в сторону города, куда ушел <span class=\"ch\" data-ch=\"menelay\">Менелай</span>, и делает несколько шагов, сначала неуверенных, потом быстрых.)"],["v","Не может быть! Пилад? О, меж людей",0,724,0,0],["v","Милей мне нет созданья. Иль Фокиду",0,725,0,0],["v","Оставил он?",0,725,0,0],["v","Как спешен шаг его!",1,725,0,0],["sd","(Улыбается.)"],["v","О, сладкий вид! В несчастье человеку",0,726,0,0],["v","Увидеть друга верного милей,",0,727,0,0],["v","Чем моряку в волнах лазурь увидеть.",0,728,0,0],["scene","Явление десятое","s12",3,12],["sd","<span class=\"ch\" data-ch=\"orest\">Орест</span> и <span class=\"ch\" data-ch=\"pilad\">Пилад</span> (в дорожном платье, без свиты)"],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Спешен шаг мой поневоле… Я из города иду…",0,729,0,0],["v","Сходки там я говор слышал, описать могу людей,",0,730,0,1],["v","Что тебя с <span class=\"ch\" data-ch=\"elektra\">Электрой</span> вместе собираются убить.",0,731,0,0],["v","Не пойму: что это значит? Что случилось, говори.",0,732,0,0],["v","Брата, сверстника и друга для меня дороже нет.",0,733,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Мы погибли, если хочешь сразу выслушать ответ.",0,734,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Разумеешь: мы с <span class=\"ch\" data-ch=\"pilad\">Пиладом</span>; не делиться ж нам, любя.",0,735,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нам с сестрой негодным трусом <span class=\"ch\" data-ch=\"menelay\">Менелай</span> явил себя.",0,736,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Муж <span class=\"ch\" data-ch=\"elena\">Елены</span>? Да каким же ты его воображал?",0,737,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Пользы было б ровно столько ж, если б он не приезжал.",0,738,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Он действительно приехал, иль ты судишь по вестям?",0,739,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ждали, ждали, а не рады мы приехавшим гостям.",0,740,0,1],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Что ж? <span class=\"ch\" data-ch=\"elena\">Елену</span> за собою он ведет, царицу зла?",0,741,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нет, не он, она супруга к нам сегодня привезла.",0,742,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Где ж теперь ахейцев стольких погубившая живет?",0,743,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","У меня, коль дом отцовский все моим еще слывет.",0,744,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","К брату отчему с какой же просьбой речь ты обратил?",0,745,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Чтоб он нас теперь с <span class=\"ch\" data-ch=\"elektra\">Электрой</span> убивать не допустил.",0,746,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Что же он? Клянусь, отказа тут не выдумал бы я.",0,747,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Увернулся, поступая, как трусливые друзья.",0,748,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","А предлог? Ведь в этом сущность! Ну, рассказывай скорей.",0,749,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Подоспел отец некстати лучших в мире дочерей.",0,750,0,1],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Что ж <span class=\"ch\" data-ch=\"tindar\">Тиндар</span>? Из-за убитой на <span class=\"ch\" data-ch=\"orest\">Ореста</span> поднял лай?<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,751,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да, и тотчас память брата предал тестю <span class=\"ch\" data-ch=\"menelay\">Менелай</span>.",0,752,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Иль не смел он злоключеньям положить твоим конец?",0,753,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О, не воин он, конечно, — но меж женщин молодец.",0,754,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Да, твои велики беды, видно, надо умирать.",0,755,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но для смерти надо прежде черепки им отобрать.",0,756,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Что ж решается? Скажи мне? Страх мне сердце пронизал.",0,757,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Жизнь и смерть — два слова только, но я ими все сказал.",0,758,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Так беги ж с сестрой, покинув отчий дом и отчий град.",0,759,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Иль ты воинов не видел — отовсюду сторожат.",0,760,0,1],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Да, на улицах встречал я загражденья из щитов.",0,761,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Право, будто неприятель в город вторгнуться готов.",0,762,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Обо мне чего ж не спросишь? Не добром и я ушел.",0,763,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не добром? Иль мук <span class=\"ch\" data-ch=\"orest\">Ореста</span> груз доселе не тяжел?",0,764,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Строфий, сам отец, разгневан, отлученье произнес.<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,765,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ссора личная иль общий политический вопрос?",0,766,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Соубийцу Клитемнестры он нечистым объявил.",0,767,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О, несчастный! Горем, видно, и тебя я заразил.",0,768,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Нравом мягче <span class=\"ch\" data-ch=\"menelay\">Менелая</span>, я покорствую судьбе.",0,769,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ну, а что, как вдруг аргосцы смерть объявят и тебе?",0,770,0,1],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Суд аргосцев мне не страшен. Надо мной фокидский суд.",0,770,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","От толпы, коль вождь коварен, и законы не спасут.",0,771,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","А коль выберет хороших, и совет ее хорош.",0,772,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Решено, сейчас же в город!",0,773,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Погоди, Орест! На что ж?",1,773,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Если граждан я уверю…",0,774,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Что творил ты правый суд…",1,774,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Мстя великую потерю…",0,775,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Тут тебя и заберут.",1,775,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что же, молча под каменья грудь подставить?",0,776,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Ты не раб.",1,776,0,0],["sd","<span class=\"ch\" data-ch=\"orest\">Орест</span> Что ж иначе?"],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Тень надежды здесь, в засаде нам была б?",0,777,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ни малейшей.",0,778,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Ну, а в город коль пойдем, надежда есть?",0,779,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Может быть.",0,780,0,1],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Тогда, конечно, лучше в город, чем засесть.",0,780,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я готов.",0,781,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Со славой лучше, чем без славы умереть.",0,782,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Избегну названья труса.",0,783,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Трус остался бы сидеть.",1,783,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Может быть, и пожалеют…",0,784,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Кровь Атридову почтут.",1,784,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Кто-нибудь отца оплачет…",0,785,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Помнят, чай, убили ж тут.",1,785,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Назовут убийцу правым…",0,785,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Только б назвали, молись.",1,785,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","И бесславно не паду я.",0,786,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Эти б речи да сбылись!..",1,786,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А сестре мы план откроем?",0,787,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Нет, клянусь богами, нет.",1,787,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ведь сейчас начнутся слезы…",0,788,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Предвещая много бед.",1,788,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Значит, выгодней молчанье?",0,789,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Время выиграем тогда.",1,789,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Есть еще одна помеха…",0,790,0,1],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Что там? Новая беда?",1,790,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нет, богинь безумья жало…",0,791,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Но с тобою буду я.",1,791,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нелегко с больным возиться.",0,792,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Иль мы больше не друзья?",1,792,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Бойся бешенства заразы.",0,793,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Ну, идем, коли идти.",1,793,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не колеблешься?",0,794,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Для дружбы в колебаньях нет пути.",1,794,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","В добрый час, мой руль надежный!",0,795,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Страж <span class=\"ch\" data-ch=\"orest\">Ореста</span> моего.",1,795,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","Обнимая <span class=\"ch\" data-ch=\"pilad\">Пилада</span> правою рукой за шею и приклонив голову к нему на грудь."],["v","Правь, Пилад, на гроб отцовский…",0,796,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Гроб отцовский? Для чего?",1,796,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Чтоб молить его охраны.",0,797,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Правдой речь твоя светла.",1,797,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Гробу ж матери ни взгляда!",0,798,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Мать врагом тебе была.",1,798,0,0],["v","Поспешим, чтоб приговором не заспели нас они.",0,799,0,0],["v","Ты возьми меня за шею, грудь к <span class=\"ch\" data-ch=\"pilad\">Пиладу</span> приклони,",0,800,0,1],["v","Через город мне не стыдно будет друга проносить:",0,801,0,0],["v","Черни, что ли, мне стыдиться? Я стыдился бы носить",0,802,0,0],["v","Имя друга, убегая от товарищей больных.",0,803,0,0],["sd","(<span class=\"ch\" data-ch=\"pilad\">Пилад</span> поднимает <span class=\"ch\" data-ch=\"orest\">Ореста</span> и медленно уносит его по направлению к городу.)"],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Добывайте друга, люди, недостаточно родных.",0,804,0,0],["v","Верьте: если слит душою с ними чуждый, то его",0,805,0,0],["v","Мириады близких кровью не заменят одного.",0,806,0,0],["scene","Второй музыкальный антракт","s13",3,13],["sp","Хор"],["str","Строфа"],["v","Златом блаженный и доблестью род!",0,807,2,0],["v","Гордо давно ль ты меж нас красовался,",0,808,0,0],["v","В волны Симунта собой любовался?",0,809,0,0],["v","Пали Атриды с сиявших высот.",0,810,2,1],["v","Снова седая творит старина",0,811,2,0],["v","Над Танталидом проклятье.",0,812,2,0],["v","Из-за златого когда-то руна<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,813,2,0],["v","Насмерть рассорились братья.",0,814,2,0],["v","Страшен был ужин из царских детей, —<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,815,0,0],["v","В море кровавой обиды",0,816,2,0],["v","Гибнут с тех пор Танталиды,",0,817,2,0],["v","Жертва за жертвой, как петли сетей.",0,818,0,0],["str","Антистрофа"],["v","Честь не бесчестной руке воздавать!",0,819,2,0],["v","Меч, перерезавший матери тело,",0,820,0,1],["v","Где неостывшая кровь почернела,",0,821,0,0],["v","Чистым ли солнца лучам обливать?",0,822,2,0],["v","Снова забредил безбожный злодей,",0,823,2,0],["v","Кончит он бредом слепого, —",0,824,2,0],["v","В ужасе смертном он вызвал у ней",0,825,2,0],["v","Стоном рожденное слово:",0,826,2,0],["v","\"Крови моей тебе, чадо, не смыть,",0,827,0,0],["v","Пепел отца ублажая:",0,828,2,0],["v","Я умираю, желая",0,829,2,0],["v","В муках бесславья <span class=\"ch\" data-ch=\"orest\">Оресту</span> изныть\".",0,830,0,1],["str","Эпод"],["v","Убившего мать",0,830,0,0],["v","Нам участь недуга больнее,",0,831,0,0],["v","И слезы в груди закипают,",0,832,0,0],["v","И жалостью сердце горит,",0,833,0,0],["v","Когда с выраженьем испуга",0,834,0,0],["v","Забродят глаза у него…",0,835,0,0],["v","И станут свирепы… и ярость",0,836,0,0],["v","Замечет больного, и с ним",0,837,0,0],["v","Начнут свои игры богини.",0,838,0,0],["v","Несчастный! Зачем он тогда,",0,839,0,0],["v","Когда из-за риз позлащенных",0,840,0,1],["v","Он нежную грудь увидал,",0,841,0,0],["v","Ножа, что отточен был местью",0,842,0,0],["v","Отцовской, не бросил ножа?..",0,843,0,0],["act","Действие третье","a4","III"],["scene","Явление одиннадцатое","s14",4,14],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","Она выходит из средней двери дворца, отдохнувшая и веселая, сначала идет на цыпочках; по мере приближения к ложу <span class=\"ch\" data-ch=\"orest\">Ореста</span> лицо ее становится тревожнее. Она сдергивает плащ, оставленный <span class=\"ch\" data-ch=\"orest\">Орестом</span> на постели, и, судорожно сжимая его, быстро подходит к хору"],["v","Скажите мне, <span class=\"ch\" data-ch=\"orest\">Ореста</span> унесло",0,844,0,0],["v","Божественным безумием отсюда?",0,845,0,0],["sp","Корифей"],["v","Нет. В Аргосе на сходке он, и там",0,846,0,0],["v","Последний бой теперь решает, верно,",0,847,0,0],["v","Простят ли вас, царевна, или нет.",0,848,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О, горе! Кто ж его идти подвигнул?",0,849,0,0],["sp","Корифей"],["v","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>. Но вестника я вижу: он",0,850,0,1],["v","Из города и с вестью об <span class=\"ch\" data-ch=\"orest\">Оресте</span>.",0,851,0,0],["scene","Явление двенадцатое","s15",4,15],["sd","Те же и вестник. Это старик крестьянин, седой, с палкой, в большой шапке и с бородой."],["sp","Вестник"],["dir","еще издали поклонившись <span class=\"ch\" data-ch=\"elektra\">Электре</span>, которая не идет ему навстречу"],["v","О горькая, оплаканная дочь",0,852,0,0],["v","Атридова, державная <span class=\"ch\" data-ch=\"elektra\">Электра</span>!",0,853,0,0],["v","Иду к тебе — увы! — с печальной вестью.",0,854,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Все этим сказано… начало — все.",0,855,0,0],["sp","Вестник"],["v","Решением пеласгов вам с <span class=\"ch\" data-ch=\"orest\">Орестом</span>",0,856,0,0],["v","Назначено сегодня умереть.",0,857,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О, горе! То, что было страшной тенью",0,858,0,0],["v","Грядущего оплакано, сбылось.",0,860,0,1],["sd","(Вестнику.)"],["v","Но самый ход борьбы, слова речей,",0,860,0,0],["v","Решивших смерть, хочу я слышать, старец.",0,861,0,0],["v","Скажи еще: под каменным дождем",0,862,0,0],["v","Иль под ножом, что пресечет дыханье",0,863,0,0],["v","Несчастие с <span class=\"ch\" data-ch=\"orest\">Орестом</span> разделю.",0,864,0,0],["sp","Вестник"],["v","Я из полей сегодня в городские",0,865,0,0],["v","Ворота шел — хотелось о судьбе",0,866,0,0],["v","Атридовых детей мне поразведать.",0,867,0,0],["v","Привязан я к семье твоей давно,",0,868,0,0],["v","Она мне помогала, и, хоть беден,",0,869,0,0],["v","Друзьям храню я верность.",0,870,0,1],["v","Посмотрю —",1,870,0,0],["v","Со всех сторон толпа, и к холму тянут,",0,870,0,0],["v","Садятся там: когда-то в первый раз",0,871,0,0],["v","На том холме, чтоб дать ответ Египту<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,872,0,0],["v","За дочерей, Данай устроил сход.",0,873,0,0],["v","И, сборище увидев, я из граждан",0,873,0,0],["v","С вопросом обращаюсь к одному:",0,874,0,0],["v","\"Иль новое что в Аргосе, иль вести",0,875,0,0],["v","Крылатые из лагеря врагов?\"",0,876,0,0],["v","А он: \"Ослеп ты, что ли, что <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,876,0,0],["v","Не видишь, — ждет его последний бой:",0,877,0,0],["v","О голове тягается\". О, лучше б",0,878,0,0],["v","Незрячим быть тогда мне. Грустный вид!",0,879,0,0],["v","<span class=\"ch\" data-ch=\"pilad\">Пилад</span> и брат твой — скорбью и недугом",0,880,0,1],["v","Размаянный и сумрачный один,",0,880,0,0],["v","Другой печаль его с любовью делит",0,881,0,0],["v","И, как дитя, больного бережет.",0,882,0,0],["v","Когда ряды наполнились, герольда",0,883,0,0],["v","Раздался крик: \"Кто хочет говорить?",0,884,0,0],["v","Вопрос: казнить иль не казнить <span class=\"ch\" data-ch=\"orest\">Ореста</span>,",0,885,0,0],["v","Что мать убил?\" Талфибий первый тут",0,886,0,0],["v","Встает, с отцом твоим громивший Трою.",0,887,0,0],["v","Оратор был уклончив, как и все<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,888,0,0],["v","Поклонники удачи: он искусно",0,889,0,0],["v","Превозносил отца, но не решился",0,890,0,1],["v","Хвалить <span class=\"ch\" data-ch=\"orest\">Ореста</span> — вкрадывались в речь",0,890,0,0],["v","Слова о двух концах, он новый способ",0,891,0,0],["v","Для родственных расчетов порицал, —",0,892,0,0],["v","Не забывая партии при этом",0,893,0,0],["v","Эгисфовой улыбки расточать.",0,894,0,0],["v","Таков уж род их. К сильному герольды",0,895,0,0],["v","Душою льнут. Талфибию друзья —",0,896,0,0],["v","Влиятельный да облеченный властью.",0,897,0,0],["v","Царь Диомед за ним в искусной речи",0,898,0,0],["v","Советовал ваш смертный приговор",0,899,0,0],["v","Изгнанием сменить благочестиво.",0,900,0,1],["v","Восторгов шум и ропота покрыл",0,901,0,0],["v","Его слова. Но вот поднялся с места",0,902,0,0],["v","Безудержным и дерзким языком",0,903,0,0],["v","Прославленный, навязанный аргосец.",0,904,0,0],["v","Шум на руку ему, и слов своих",0,905,0,0],["v","Он выбирать не любит, мастер судей<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,906,0,0],["v","Самих еще запутать. (Мед в устах",0,907,0,0],["v","И зло в душе — такой советчик язва.",0,908,0,0],["v","Зато совет и умный и благой",0,909,0,0],["v","Пусть не сейчас, но польза увенчает;",0,910,0,1],["v","Властям судить оратора нельзя,",0,911,0,0],["v","Не посмотрев, что выйдет, и советчик",0,912,0,0],["v","Лишь по плодам познается, как врач.)<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,913,0,0],["v","О каменной для вас с <span class=\"ch\" data-ch=\"orest\">Орестом</span> казни",0,914,0,0],["v","Он вопиял, <span class=\"ch\" data-ch=\"tindar\">Тиндаром</span> наущен.",0,915,0,0],["v","Но вот встает оратор — не красавец,<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,916,0,0],["v","Но крепкий муж: не часто след ноги",0,917,0,0],["v","На площади аргосской оставляя,",0,918,0,0],["v","Свою он землю пашет — на таких",0,920,0,1],["v","Теперь страна покоится. Не беден",0,920,0,0],["v","Он разумом, коль случай есть порой",0,921,0,0],["v","Помериться в словесном состязанье,",0,922,0,0],["v","А жизнию он — безупречный муж.",0,922,0,0],["v","Оратор наш не смерти для <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,923,0,0],["v","Потребовал — венца, что не сробел",0,924,0,0],["v","Он за отца вступиться и пред казнью",0,925,0,0],["v","Безбожницы лихой не отступил.",0,925,0,0],["v","А то потом хоть и копья для битвы",0,926,0,0],["v","Не доставай, походы позабудь.",0,927,0,0],["v","Охотника всегда найдешь без мужа",0,927,0,0],["v","В соблазны жен скучающих вводить —",0,928,0,0],["v","И воину порочить ложе. Славно",0,929,0,0],["v","Он говорил и добрым по душе.",0,930,0,1],["v","Замолкшего твой брат <span class=\"ch\" data-ch=\"orest\">Орест</span> сменяет:",0,930,0,0],["v","\"Владетели Инаховой земли,",0,931,0,0],["v","Не меньше вас я охранял, чем тень",0,932,0,0],["v","Отцовскую, когда убийцей стал я.",0,933,0,0],["v","Коль словом вы сегодня освятите",0,934,0,0],["v","Мужеубийство, граждане, вослед",0,935,0,0],["v","Представиться вам не замедлит выбор:",0,935,0,0],["v","Иль умирать, иль быть рабами жен.",0,936,0,0],["v","⟨Не то, что надо, сделать вы готовы!",0,937,0,0],["v","Я ту, что ложе моего отца",0,938,0,0],["v","Изменой запятнала, уничтожил.",0,939,0,0],["v","Меня убейте — и закон исчезнет,",0,940,0,1],["v","Без страха будут люди убивать,⟩",0,941,0,0],["v","О, дерзости у них, поверьте, хватит…\"",0,942,0,0],["v","Казалось, был и прав он, но рассудком",0,943,0,0],["v","Не убедил собранья, и толпу",0,944,0,0],["v","Другой увлек оратор — жаждой крови.",0,945,0,0],["v","Едва-едва <span class=\"ch\" data-ch=\"orest\">Оресту</span> удалось",0,946,0,0],["v","Добиться, чтобы вам самоубийством",0,947,0,0],["v","Дозволили сегодня кончить жизнь.",0,948,0,0],["v","<span class=\"ch\" data-ch=\"pilad\">Пилад</span> его домой ведет со сходки.",0,950,0,1],["v","И плачет он, и воплями друзья",0,950,0,0],["v","В последний раз <span class=\"ch\" data-ch=\"orest\">Ореста</span> провожают.",0,951,0,0],["v","Да, зрелище печальное глазам",0,952,0,0],["v","Откроется уж скоро, а покуда",0,953,0,0],["v","Готовь ножи иль петли, а на солнце",0,954,0,0],["v","Вам не глядеть. Ни царский не поможет",0,955,0,0],["v","Ваш сан, ни Феб с треножником своим,",0,955,0,0],["v","Пифийский бог, вас погубивший, дети.",0,956,0,0],["sd","(Уходит.)"],["sd","Во время рассказа вестника <span class=\"ch\" data-ch=\"elektra\">Электра</span> поникла головой и продолжает некоторое время стоять потупившись. Только слова корифея заставляют ее поднять голову."],["scene","Явление тринадцатое","s16",4,16],["sd","<span class=\"ch\" data-ch=\"elektra\">Электра</span> одна."],["sp","Корифей"],["v","О злополучная, еще к земле",0,957,0,0],["v","Лицо ты молча клонишь, но рыданьем",0,958,0,0],["v","И стонами готова разразиться.",0,959,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","монодия"],["str","Строфа"],["v","Тебе ланит моих, земля пеласгов,",0,960,0,1],["v","Серебряным разорванным ногтем,",0,960,0,0],["v","Первая скорби кровь;",0,961,2,0],["v","Я голову ударами осыплю",0,962,0,0],["v","В усладу богине прекрасной,<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,963,2,0],["v","Нежной жертве подземных!",0,964,2,0],["v","Острым да скосишь железом ты,",0,965,2,0],["v","Край киклопов, стеная,",0,966,2,0],["v","Локоны в день печали.",0,967,2,0],["v","Плач да поднимется, плач!",0,968,2,0],["v","Царство теней открыто",0,969,2,0],["v","Прежним вождям Эллады.",0,970,2,1],["str","Антистрофа"],["v","Вас нет, вас больше нет, Пелопа дети.",0,970,0,0],["v","Блаженным твой завиден был удел,",0,971,0,0],["v","Тантала славный род.",0,972,2,0],["v","Небесная вас зависть погубила,",0,973,0,0],["v","Аргосцев кровавое слово.",0,974,2,0],["v","Горе племени смертных,",0,975,2,0],["v","Слез и страданий полному.",0,976,2,0],["v","Мойры удары верны,",0,977,2,0],["v","Мойры шаги так тихи!",0,978,2,0],["v","Беды — наследницы зол…",0,979,2,0],["v","В смене жизней печальных",0,980,2,1],["v","Миг ни один не верен.",0,980,2,0],["str","Строфа I"],["v","О, если б я к камню взвилася…",0,981,2,0],["v","Олимпа обломок,",0,982,2,0],["v","Меж небом и нами",0,982,2,0],["v","Повис на цепях золотых он",0,983,0,0],["v","И кружится вихрем!",0,984,0,0],["v","Я Танталу старому там бы",0,984,0,0],["v","Надгробную 6 песню провыла:",0,985,0,0],["v","Из крови, из крови его родились",0,986,0,0],["v","Отцы наши, зревшие ужас,",0,986,0,0],["str","Строфа II"],["v","С тех пор как, легче ветра,",0,987,0,0],["v","Четыре кобылицы",0,988,0,0],["v","Пелоповы, взметая",0,988,0,0],["v","Прибоя пыль, летели,",0,989,0,0],["v","С тех пор как труп Миртила",0,990,0,1],["v","Столкнул в седую пену",0,991,0,0],["v","На побережье диком",0,992,0,0],["v","Гереста Танталид.",0,993,0,0],["str","Строфа III"],["v","Оттуда на дом наш проклятье<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,994,0,0],["v","И слезы — на пастбищах конных,",0,995,0,0],["v","Которыми славен Атрей,",0,996,0,0],["v","Ягненка руном золотым",0,997,0,0],["v","Явил несказанное диво,",0,998,0,0],["v","Сын Майи на гибель Атрею.",0,1000,0,1],["v","Оттуда ж бег крылатый",0,1000,2,0],["v","Переменила Гелия",0,1001,2,0],["v","Златая колесница:",0,1002,2,0],["v","На Запад путь забыв,",0,1003,2,0],["v","С одною кобылицею",0,1003,2,0],["v","К Заре вернулся бог.",0,1004,2,0],["str","Строфа IV"],["v","В небе — златых Плеяд семизвездных",0,1005,0,0],["v","Перечертил Громовержец пути,",0,1006,0,0],["v","Здесь же — на смену смертям",0,1006,0,0],["v","Новые смерти, здесь ужин",0,1007,0,0],["v","С именем связан Фиеста;",0,1008,0,0],["v","С жаждой преступных объятий",0,1009,0,0],["v","Критянки ложе коварной,",0,1010,0,1],["v","Здесь для отца и для нас",0,1010,0,0],["v","К тяжким оковам Пелопа<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,1011,2,0],["v","Новые звенья прибавил",0,1012,2,0],["v","Зевс-Громовержец.",0,1012,2,0],["sp","Корифей"],["v","А вот и <span class=\"ch\" data-ch=\"orest\">Орест</span>, царевна,",0,1013,2,0],["v","На смерть осужденный…",0,1014,2,0],["v","С ним, брата вернее,",0,1014,2,0],["v","<span class=\"ch\" data-ch=\"pilad\">Пилад</span> неразлучен.",0,1015,2,0],["v","Недужного трепетен шаг,",0,1016,0,0],["v","Но в ногу товарищ шагает:",0,1016,0,0],["v","Коню изнемогшему так",0,1017,0,0],["v","Припряженный конь помогает.",0,1018,0,0],["scene","Явление четырнадцатое","s17",4,17],["sd","Пилад, заплаканный, ведет, нежно поддерживая, бледного, но сравнительно спокойного <span class=\"ch\" data-ch=\"orest\">Ореста</span>. За ним издали и робко следует редкая толпа друзей. Мало-помалу они расходятся, прощаясь с <span class=\"ch\" data-ch=\"orest\">Орестом</span> и выражая ему знаками сочувствие. Несколько минут молчания. <span class=\"ch\" data-ch=\"orest\">Орест</span> отводит руки <span class=\"ch\" data-ch=\"pilad\">Пилада</span> и направляется к <span class=\"ch\" data-ch=\"elektra\">Электре</span>. Губы его сжаты, в глазах решимость. <span class=\"ch\" data-ch=\"elektra\">Электра</span>, <span class=\"ch\" data-ch=\"orest\">Орест</span> и <span class=\"ch\" data-ch=\"pilad\">Пилад</span>."],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","пока <span class=\"ch\" data-ch=\"orest\">Орест</span> медленно приближается к ней"],["v","О, горе мне! Открытая могила,",0,1018,0,0],["v","Пылающий костер и жертва их!",0,1019,0,0],["v","Увы! Увы! Ужель я вижу брата",0,1020,0,1],["v","В последний раз?.. иль я с ума схожу?",0,1021,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","В молчании, без воплей малодушных",0,1022,0,0],["v","Прими судеб решение: да, слез",0,1023,0,0],["v","Достойны мы, но покорись, <span class=\"ch\" data-ch=\"elektra\">Электра</span>.",0,1024,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","В молчании?.. Сиянье солнца нам",0,1025,0,0],["v","Хотят закрыть… а я… молчать я буду?",0,1026,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не добивай решением толпы",0,1027,0,0],["v","Убитого… Иль мук <span class=\"ch\" data-ch=\"orest\">Оресту</span> мало?",0,1028,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","плача и ударяя себя в голову"],["v","О, молодость без радостей, о, цвет,",0,1029,0,0],["v","Без времени подкошенный… Увы!",0,1030,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","борется с собой"],["v","О боги! Эти цепи слабых душ",0,1030,0,0],["v","Так тяжелы… Не надо слез, <span class=\"ch\" data-ch=\"elektra\">Электра</span>.",0,1031,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Пред смертию не плакать не могу:",0,1032,0,0],["v","О жизни все, ее теряя, плачут.",0,1033,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Часы не ждут: иль петлю примощай,",0,1034,0,0],["v","Иль меч остри, а выбор неизбежен.",0,1035,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Орест, убей меня, иль дашь руке",0,1036,0,0],["v","Аргосской дочь Атридову позорить?",0,1037,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Убийца я и мститель, но сестре",0,1038,0,0],["v","Я не палач, с меня довольно крови…",0,1039,0,0],["v","Ты выбирай, ты и казни себя.",0,1040,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Пусть будет так, как ты сказал. Дыханье",0,1040,0,0],["v","Мне за тобой прервет твой острый меч.",0,1041,0,0],["sd","(Протягивая ему руки.)"],["v","Но дай обнять тебя и позабыться.",0,1042,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","приближаясь, кладет ей руки на плечи"],["v","Печальная услада… В ней тебе",0,1043,0,0],["v","Не откажу… коли так сладко нежным",0,1044,0,0],["v","Рукам добычу смерти обвивать.",0,1045,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","лаская <span class=\"ch\" data-ch=\"orest\">Ореста</span>"],["v","Родимый мой… Желанный брат… и сердцем",0,1045,0,0],["v","И жизнью слиты мы, о мой <span class=\"ch\" data-ch=\"orest\">Орест</span>!..",0,1046,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","отвечая ее ласкам, нежно"],["v","Ты нежностью мне растопила сердце,",0,1047,0,0],["v","Тебя обнять и я горю… Чего ж",0,1048,0,0],["v","Стыдиться? Грудь сестры… тебя лаская,",0,1049,0,0],["v","С женою я прощаюсь и детьми.",0,1050,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Увы! Увы!",0,1051,0,0],["v","Как сделать нам, чтоб меч один убил нас",0,1052,0,0],["v","И вместе лечь в кедровый гроб, Орест?",0,1053,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да, сладкая надежда… Но, Электра,",0,1054,0,0],["v","Тут помощь нам нужна… а мы одни…",0,1055,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль за тебя там не замолвил слова",0,1056,0,0],["v","Отцовский брат, предатель <span class=\"ch\" data-ch=\"menelay\">Менелай</span>?",0,1057,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не показал лица… Когда престола",0,1058,0,0],["v","Сияние слепит — что мы ему?",0,1059,0,0],["v","Но забывать, что честь Агамемнона",0,1060,0,1],["v","В нас с жизнию слилась, мы не должны.",0,1060,0,0],["v","Чтоб умереть, нам рук чужих не надо.",0,1061,0,0],["v","И Аргосу я царский дух явлю.",0,1062,0,0],["v","А ты, когда мечом пронзится печень,",0,1063,0,0],["v","В дерзании <span class=\"ch\" data-ch=\"orest\">Ореста</span> повтори.",0,1063,0,0],["sd","(<span class=\"ch\" data-ch=\"pilad\">Пиладу</span>.)"],["v","Ты ж, друг <span class=\"ch\" data-ch=\"pilad\">Пилад</span>, свидетель жертвы будешь.",0,1064,0,0],["v","Не правда ли, что, трупы обрядив,",0,1065,0,0],["v","В отцовский гроб снесешь ты их и вместе",0,1066,0,0],["v","Зароешь там? Я ухожу, прости!",0,1066,0,0],["v","Не говорить теперь, а делать время.",0,1067,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Постой… Тебя впервые упрекну:",0,1068,0,0],["v","Иль думаешь, что я нуждаюсь в жизни,",0,1069,0,0],["v","Когда со мной <span class=\"ch\" data-ch=\"orest\">Ореста</span> больше нет?",0,1070,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да, жить со мной, но умирать зачем же?",0,1070,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Спроси: зачем мне без <span class=\"ch\" data-ch=\"orest\">Ореста</span> жить?",0,1071,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты разве мать убил, как этот горький?",0,1072,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Я помогал ему и с ним умру.",0,1073,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нет, сбереги себя отцу, со мною",0,1074,0,0],["v","Не умирай, есть город у тебя,",0,1075,0,0],["v","А я изгой. Ждет дом тебя отцовский,",0,1075,0,0],["v","И верная богатства гавань ждет.",0,1076,0,0],["v","Сестру тебе я обручил, я друга",0,1077,0,0],["v","Хотел почтить — увы! Печальный брак",0,1078,0,0],["v","<span class=\"ch\" data-ch=\"elektra\">Электру</span> ждет. Ну что ж! Другое ложе",0,1079,0,0],["v","Найдешь детей рождать, а нам свойство",0,1080,0,1],["v","С тобою, видно, боги не судили.",0,1080,0,0],["v","Ты, слово «друг» рождавший на устах,",0,1081,0,0],["v","Прости! С тобою радость остается,",0,1082,0,0],["v","Мы ж, мертвые, не видим светлых снов.",0,1083,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Как помыслы мои <span class=\"ch\" data-ch=\"orest\">Оресту</span> чужды!",0,1084,0,0],["sd","(Торжественно.)"],["v","О, заклинаю землю, пусть она",0,1085,0,0],["v","На лоно прах не примет мой, и светлый",0,1085,0,0],["v","Молю эфир, да не приемлет духа",0,1086,0,0],["v","Пиладова, коль, другу изменив,",0,1087,0,0],["v","За жизнь цепляться буду.",0,1088,0,0],["v","Убивали",1,1088,0,0],["v","Не вместе ль мы? и если мой совет",0,1089,0,0],["v","Тебя на казнь привел, не заодно ли",0,1090,0,1],["v","И умереть должны мы в наказанье?",0,1090,0,0],["v","<span class=\"ch\" data-ch=\"elektra\">Электра</span> мне обручена, и в ней",0,1091,0,0],["v","Я чту жену. Иль мог бы благородный",0,1092,0,0],["v","Я дать ответ в Фокиде пред кремлем",0,1093,0,0],["v","Дельфийским, почему друзей покинул",0,1094,0,0],["v","В несчастии, а не тогда, как дни",0,1095,0,0],["v","Счастливые текли? Итак, с тобою",0,1096,0,0],["v","Мы делим смерть. Но отчего б ее",0,1097,0,0],["v","Не разделил с обоими невольно",0,1098,0,0],["v","Предатель ваш, безбожный <span class=\"ch\" data-ch=\"menelay\">Менелай</span>?",0,1099,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О, если бы мне труп его увидеть.",0,1100,0,1],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Повремени же ты кончать с собой.",0,1101,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Еще бы нет, коль кара ждет злодея.",0,1102,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["dir","оглядываясь на хор, тихо"],["v","Здесь уши есть — не распускай язык.",0,1103,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Напрасный страх, Пилад, сердца их с нами.",0,1104,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["dir","шепотом"],["v","Еленин труп оплачет <span class=\"ch\" data-ch=\"menelay\">Менелай</span>.",0,1105,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Готовность есть, но мало — способ нужен.",0,1106,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["dir","указывая на дом"],["v","Зарежем: здесь она ведь, под рукой.",0,1107,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Печатями добро оберегает…",0,1108,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Не для себя — ведь ей Аид жених.",0,1109,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да справишься ль? С ней свита азиатов.",0,1110,0,1],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Им Фригия отчизна — не страшны.",0,1111,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Хранители зеркал и благовоний.",0,1112,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Иль негою и здесь окружена?",0,1113,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","В Элладе ей чертоги тесны стали.",0,1114,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Но раб против свободного — ничто.",0,1115,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Две смерти мне не страшны в этом деле.",0,1116,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","И мне, Орест, коль за тебя я мщу.",0,1117,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но объясни мне план — что надо делать?",0,1118,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Готовые на смерть, мы входим в дом.",0,1119,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Желанного конца еще не вижу.",0,1120,0,1],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Там жалобой царице тронем слух.",0,1121,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Чтоб плакала, а в сердце ликовала.",0,1122,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Вот именно, точь-в-точь как мы, <span class=\"ch\" data-ch=\"orest\">Орест</span>.",0,1123,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А самый ход борьбы тобой обдуман?",0,1124,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Под ризами мы затаим мечи.",0,1125,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но как убить средь челяди <span class=\"ch\" data-ch=\"elena\">Елену</span>?",0,1126,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Придется их, конечно, распугнуть.",0,1127,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А крикунов, пожалуй, перерезать.",0,1128,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Нам прочее укажет ход вещей.",0,1129,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","тихо"],["v","А прочее, конечно, смерть <span class=\"ch\" data-ch=\"elena\">Елены</span>?",0,1130,0,1],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Да, смерть ее, — сознаться не стыжусь:",0,1131,0,0],["v","Убийство было бы позорно, коли скромной",0,1132,0,0],["v","Грозил бы меч, отточенный тайком,",0,1133,0,0],["v","Но от лица Эллады мы караем",0,1134,0,0],["v","Преступницу: за вдов, и за сирот,",0,1135,0,0],["v","И за отцов убитых мы караем.",0,1136,0,0],["v","Мы ликовать и жертвами за нас",0,1137,0,0],["v","Благодарить богов заставим греков,",0,1138,0,0],["v","Кровавый долг с лихой жены взыскав.",0,1139,0,0],["v","И с той поры не матереубийцей,",0,1140,0,1],["v","Убийцею <span class=\"ch\" data-ch=\"elena\">Елены</span> прослывешь",0,1140,0,0],["v","Ты в их устах, из-за которой крови",0,1141,0,0],["v","Так много пролилось. Не быть тому,",0,1142,0,0],["v","Чтоб <span class=\"ch\" data-ch=\"menelay\">Менелай</span> блаженствовал на прахе",0,1143,0,0],["v","И брата, и детей его, жены, —",0,1144,0,0],["v","Иль нет, ее не потревожим праха.",0,1145,0,0],["v","Но чтобы он наследовал твой дом",0,1145,0,0],["v","С женой, ему копьем Агамемнона",0,1146,0,0],["v","Добытою, — пусть мне не жить, коль меч",0,1147,0,0],["v","Не обнажу против <span class=\"ch\" data-ch=\"elena\">Елены</span>. Если ж",0,1148,0,0],["v","Наш замысел обрушится, то в пепел",0,1149,0,0],["v","Мы обратимся вместе со дворцом,",0,1150,0,1],["v","И все же честь останется за нами,",0,1150,0,0],["v","И славных дел бог смерти не сотрет.",0,1151,0,0],["sp","Корифей"],["v","Всем женщинам отныне ненавистна",0,1152,0,0],["v","<span class=\"ch\" data-ch=\"tindar\">Тиндара</span> дочь, позорящая пол.",0,1153,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О, верного нам друга не заменит",0,1154,0,0],["v","Ни золото, ни трон, и предпочесть",0,1155,0,0],["v","Толпу участью доблестного сердца",0,1156,0,0],["v","Один безумец может. Ты, Пилад,",0,1157,0,0],["v","С Эгисфом мне покончить помогая,",0,1158,0,0],["v","Делил со мной опасность, а теперь,",0,1159,0,0],["v","Когда я всеми брошен, планом мести",0,1160,0,1],["v","Мне сердце радуешь. Но докучать",0,1161,0,0],["v","Я не хочу хвалой тебе. Коль жизнью",0,1162,0,0],["v","Пожертвовать должны мы, сладки нам",0,1163,0,0],["v","Предателей стенания и гибель.",0,1164,0,0],["v","Атрида кровь во мне. Отец мой был",0,1165,0,0],["v","Игемоном Эллады признан, властью",0,1166,0,0],["v","Тирана не владея, он богам<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,1167,0,0],["v","Могуществом был равен, — смертью рабской",0,1168,0,0],["v","Я имени его не оскверню",0,1170,0,1],["v","И <span class=\"ch\" data-ch=\"menelay\">Менелая</span> славой не венчаю.",0,1171,0,0],["v","Но если бы убить и уцелеть",0,1172,0,0],["v","Нам рок сулил… О, счастье!.. о, надежда!..",0,1173,0,0],["v","«Убить и уцелеть» — четою слов",0,1174,0,0],["v","Крылатою отрадно сердце нежить,",0,1175,0,0],["v","И сладость их доступна бедняку.",0,1176,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Мне кажется, что я открыла способ",0,1177,0,0],["v","Спасти тебя, <span class=\"ch\" data-ch=\"pilad\">Пилада</span> и самой",0,1178,0,0],["v","За вами вслед спастись. Послушай, брат.",0,1179,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","То — божий перст. В твой гибкий ум я верю.",0,1180,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","<span class=\"ch\" data-ch=\"orest\">Оресту</span> и <span class=\"ch\" data-ch=\"pilad\">Пиладу</span>"],["v","Внимания обоих попрошу.",0,1180,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я жду, сестра, есть сладость даже в самом",0,1181,0,0],["v","Томлении, когда мы счастья ждем.",0,1182,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Ты знаешь дочь <span class=\"ch\" data-ch=\"elena\">Елены</span>? Как не знать?",0,1183,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Питомицу покойной, Гермиону?",0,1184,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Она пошла могилу навестить.",0,1185,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Зачем? И где ты видишь тут надежду?",0,1186,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Фиал излить на материнский гроб.",0,1187,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Спасения я все-таки не вижу.",0,1188,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Назад пойдет — чем не заложник нам?",0,1189,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но чем же нам троим залог поможет?",0,1190,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Как — чем, Орест? А если <span class=\"ch\" data-ch=\"menelay\">Менелай</span>,",0,1190,0,0],["v","Мстя за жену, расправиться с тобою,",0,1191,0,0],["v","С ним и со мной захочет, нас убив, —",0,1192,0,0],["v","<em>Нас</em>, говорю: ведь дружбою мы слиты, —",0,1193,0,0],["v","Приставь тогда к девичьей шее нож,",0,1194,0,0],["v","И если царь, жены окровавленный",0,1195,0,0],["v","Увидев труп, заступится за нас,",0,1196,0,0],["v","Дочь возврати ему. Но если, гнева",0,1197,0,0],["v","Не победив, упорствовать в твоей",0,1198,0,0],["v","Он казни не оставит, Гермиону",0,1199,0,0],["v","Заколешь ты. Но, вероятно, он",0,1200,0,1],["v","Остынуть не замедлит: сердца мужа",0,1201,0,0],["v","В спартанце нет. Вот почему, <span class=\"ch\" data-ch=\"orest\">Орест</span>.",0,1202,0,0],["v","В спасенье верю я. Я все сказала.",0,1203,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Рассудком ты мужским одарена",0,1204,0,0],["v","И красотой отмечена меж женщин.",0,1205,0,0],["v","Ужель тебе, Электра, умирать?",0,1206,0,0],["v","Ужель тебе, Пилад, ее лишаться?",0,1207,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","О, если бы на светлый брачный пир",0,1208,0,0],["v","Для ней чертог фокидский отворился!",0,1210,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","<span class=\"ch\" data-ch=\"elektra\">Электре</span>"],["v","Когда ж назад, скажи, она пойдет?",0,1210,0,0],["v","Мне все теперь удачу обещает,",0,1211,0,0],["v","Лишь завладеть успели б мы отца",0,1212,0,0],["v","Безбожного детенышем любимым.",0,1213,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Она теперь уже недалеко:",0,1214,0,0],["v","Он наш, Орест, коли расчет мой верен.",0,1215,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Отлично. Ты, Электра, у дворца",0,1215,0,0],["v","Останешься царевну караулить.",0,1216,0,0],["v","И если бы, пока не удалось",0,1217,0,0],["v","Покончить нам расправы, увидала",0,1218,0,0],["v","Кого-нибудь из близких ты, иль муж",0,1219,0,0],["v","Еленин к нам в чертоги устремился, —",0,1220,0,1],["v","Ты закричишь, иль в двери застучишь,",0,1220,0,0],["v","Иль голосом нам знак подашь. Войдем,",0,1221,0,0],["v","На этот бой последний изготовив",0,1222,0,0],["v","Свои мечи, товарищ трудовой.",0,1223,0,0],["sd","(Точат мечи, потом складывают их на землю и, опуская руки, молят тень Агамемнона.)"],["v","О мой отец, в обитель ночи черной",0,1224,0,0],["v","И твой чертог да снизойдут слова!",0,1225,0,0],["v","К тебе мольбу склоняем мы — несчастен<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,1225,0,0],["v","Из-за тебя твой сын; он за тебя",0,1226,0,0],["v","Неправедно гоним и предан братом",0,1227,0,0],["v","Твоим за то, что был и прав и смел.",0,1228,0,0],["v","О, помоги нам захватить <span class=\"ch\" data-ch=\"elena\">Елену</span>,",0,1229,0,0],["v","Союзником для дерзостных явись!",0,1230,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Приди, отец, коль до глубин подземных",0,1230,0,0],["v","Твоих детей доходят голоса.",0,1231,0,0],["v","Здесь за тебя, отец, мы умираем.",0,1232,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Агамемнон, от родича мольбу<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,1233,0,0],["v","Прими, детей спаси своих, блаженный.",0,1233,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я мать убил.",0,1234,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["sd","Я подавала меч."],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Я победил рождавшуюся робость.",0,1235,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","То месть была, родимый, за тебя.",0,1236,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Я памяти твоей хранила верность.",0,1236,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","О, тронься же укорами детей.",0,1237,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Из слез тебе творю я возлиянье.",0,1238,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","И стоны в дар тебе я приношу.",0,1239,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Ну, будет же. За дело! Заклинанья,",0,1240,0,1],["v","Коль ранить могут землю, он слыхал.",0,1241,0,0],["v","Ты, предок наш, о Зевс, и ты, о Правда,",0,1242,0,0],["v","Пошлите нам удачу всем троим!",0,1243,0,0],["v","Ему, и мне, и ей уж жребий вынут,",0,1244,0,0],["v","И всем один, но что скрывает он —",0,1245,0,0],["v","Жизнь или смерть, — еще мы не узнали.",0,1246,0,0],["sd","(Уходит с <span class=\"ch\" data-ch=\"orest\">Орестом</span> в дом.)"],["scene","Вместо третьего музыкального антракта","s18",4,18],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["sd","Строфа Жены, Микен жены милые, Старого града пеласгов краса!"],["sp","Хор"],["v","Что, владычица? У народа так",0,1247,0,0],["v","Ты в устах еще величаешься.",0,1250,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Одни из вас пусть на дорогу выйдут.",0,1251,0,0],["v","Других я здесь прошу посторожить.",0,1252,0,0],["sp","Хор"],["sd","От кого ж, дитя, Сторожить-то нам?"],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Страх берет меня, не пришел бы кто.",0,1253,0,0],["v","Там кровавое совершается",0,1254,0,0],["v","Дело, новой бы не приспеть беде.",0,1255,0,0],["sp","Первый парастат"],["v","Так поспешим — я становлюсь на эту",0,1256,0,0],["v","Тропу: она на солнечный восход.",0,1257,0,0],["sp","Второй парастат"],["v","А я на ту — она идет на запад.",0,1260,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Зрачков блестящих взор поочередно вы",0,1261,0,0],["v","Направо бросите, налево бросите!",0,1262,0,0],["sp","Первое полухорие"],["sd","Да, царевна, да!"],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["str","Антистрофа"],["v","Через нависшие локоны",0,1263,0,0],["v","Дайте свободу вы звездам зениц.",0,1264,0,0],["sd","Второе полухорие"],["v","Кто-то ходит там. У чертога я",0,1265,0,0],["v","Поселянина заприметила.",0,1270,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Погибли мы. Он об охоте тайной",0,1271,0,0],["v","С оружием врагов оповестил.",0,1272,0,0],["sp","Первое полухорие"],["sd","Никого там нет: Брось тревожиться."],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","ко второму парастату"],["v","Нет опасности в вашу сторону?",0,1273,0,0],["v","Доброй вестью ты уверь меня,",0,1274,0,0],["v","Что пуста тропа пред воротами.",0,1275,0,0],["sp","Второй парастат"],["v","Отсюда все благополучно, надо",0,1276,0,0],["v","Смотреть от них. А здесь данайцев нет.",0,1277,0,0],["sp","Первый парастат"],["v","Толпы и я вокруг не замечаю.",0,1280,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль за воротами?.. Сейчас послушаю.",0,1281,0,0],["sd","(Слушает. Пауза. Громко.)"],["v","Оге! Что медлите? Иль свежей кровию",0,1282,0,0],["v","Мечи не красятся?",0,1283,1,0],["sd","(После минутного молчания.)"],["str","Эпод"],["v","Не слышат, нет… О, горе, горе мне,",0,1284,0,0],["v","Иль красота мечи заворожила?",0,1285,0,0],["v","А того гляди, что с оружием",0,1286,1,0],["v","Из аргосцев кто к ней на выручку",0,1287,1,0],["v","Прянет, дерзостный…",0,1290,1,1],["sd","(Хору.)"],["v","Глядите же прилежней. Отдыхать",0,1290,0,0],["v","Еще не час. Проворнее, кто вправо,",0,1291,0,0],["v","Кто влево все вниманье устреми.",0,1292,0,0],["sp","Хор"],["v","Поочередно мы и без того тропы",0,1293,0,0],["v","Из глаз не выпустим.",0,1294,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","голос за сценой"],["v","О Аргос, о пеласги, погибаю…",0,1295,0,0],["sp","Первый парастат"],["v","Вы слышите: расправа началась.",0,1296,0,0],["sp","Второй парастат"],["v","Почудилось ли мне? <span class=\"ch\" data-ch=\"elena\">Елена</span> стонет…",0,1297,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","руки к небу"],["v","Зевса сила предвечная,",0,1298,0,0],["v","О, поддержи,",0,1299,2,0],["v","Боже великий, товарищей!",0,1300,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","голос за сценой"],["v","О, где ты, Менелай? О, поспеши…",0,1301,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Бейте, губите, разите!",0,1302,0,0],["v","Меч двулезвийный",0,1303,0,0],["v","В тело ее погружайте.",0,1304,0,0],["v","Мужа, отца обесславила,",0,1305,0,0],["v","Греков губила",0,1306,0,0],["v","Там, у пучины Скамандра,",0,1307,0,0],["v","Где от железа стрел",0,1308,0,0],["v","Слезы рождали слезы…",0,1310,0,1],["act","Действие четвертое","a5","IV"],["scene","Явление пятнадцатое","s19",5,19],["sd","В конце слов <span class=\"ch\" data-ch=\"elena\">Елены</span> — Гермиона, за ней служанка с пустым фиалом."],["sp","Корифей"],["v","Остановись… До слуха долетел",0,1311,0,0],["v","Какой-то шум… со стороны дороги.",0,1312,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","шепотом"],["v","Да, женщины… Под самую резню",0,1313,0,0],["v","Царевна подоспела, Гермиона…",0,1314,0,0],["v","Мы голоса понизим, чтобы в сеть",0,1315,0,0],["v","Доверчивей влетела наша птичка.",0,1316,0,0],["v","О, добрая добыча… Звезды глаз",0,1317,0,0],["v","Завесьте же, глядите равнодушней,",0,1318,0,0],["v","Взор потушу и я, как будто дом",0,1319,0,0],["v","Еще не орошался кровью.",0,1320,0,1],["sd","(К подходящей Гермионе.)"],["v","Дева,",0,1320,4,0],["v","Успела ль ты, подземным сотворив",0,1321,0,0],["v","Мольбу богам, могилу возлияньем",0,1322,0,0],["v","Царицыну и локоном почтить?",0,1323,0,0],["sp","Гермиона"],["v","Покойную мольбой я ублажила,",0,1324,0,0],["v","Но в сердце страх вселил далекий стон,",0,1325,0,0],["v","Чуть слышный стон из царского чертога.",0,1325,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Что ж? Или слез не стоит жребий наш?",0,1326,0,0],["sp","Гермиона"],["v","О, что случилось? Ты меня пугаешь.",0,1327,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","<span class=\"ch\" data-ch=\"orest\">Орест</span> и я осуждены на казнь.",0,1328,0,0],["sp","Гермиона"],["v","Не может быть! Вы, вы, мои родные?",0,1329,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Так решено, царевна: мы умрем.",0,1330,0,1],["sp","Гермиона"],["v","И этот стон, он вызван был решеньем?",0,1330,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Он воплями царицу умолял.",0,1331,0,0],["sp","Гермиона"],["v","Кто умолял? Скажи ясней, <span class=\"ch\" data-ch=\"elektra\">Электра</span>.",0,1332,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Несчастный брат молил ее за нас.",0,1333,0,0],["sp","Гермиона"],["v","Так правдою чертог ваш оглашался.",0,1334,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","На что уж больше правды? Но войдем,",0,1335,0,0],["v","И, к матери блаженной припадая,",0,1336,0,0],["v","Ее за нас и с нами умолять,",0,1337,0,0],["v","Не правда ли, ты будешь? Иль не может",0,1338,0,0],["v","Избавить нас от смерти <span class=\"ch\" data-ch=\"menelay\">Менелай</span>?",0,1339,0,0],["v","О, матерью взращенная моею,",0,1340,0,1],["v","Ужель детей ее тебе не жаль?",0,1341,0,0],["v","Борьба нас ждет… Но наша ты… Войдем же.",0,1342,0,0],["v","Последний луч надежды над тобой…",0,1343,0,0],["sp","Гермиона"],["v","Пойдем, пойдем… Зачем ты медлишь? В доме",0,1344,0,0],["v","Я, кажется, не лишняя… Смелей…",0,1345,0,0],["sd","(Входит в дом.)"],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Гей вы, товарищи, мечи готовьте… Наша…",0,1346,0,0],["sp","Гермиона"],["dir","голос из дома"],["v","О, ужас! Кто это?..",0,1347,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","голос из дома"],["v","Ни слова! Твой приход",1,1347,0,0],["v","Спасителен… Но не тебе, девица…",0,1348,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Держите же ее да голый меч",0,1349,0,0],["v","Приблизить ей не бойтесь к шее нежной,",0,1350,0,1],["v","Чтоб <span class=\"ch\" data-ch=\"menelay\">Менелай</span> здесь воинов нашел,",0,1350,0,0],["v","А не рабов фригийских… и награду",0,1351,0,0],["v","Достойную приял трусливых душ.",0,1352,0,0],["sp","Хор"],["str","Строфа"],["v","Смелее, подруги! Пусть шум голосов",0,1353,0,0],["v","Сливается с воплем чертога,",0,1354,0,0],["v","Пока не свершилась борьба…",0,1355,0,0],["sp","Корифей"],["v","Да не вселит в аргосцев женский вопль",0,1355,0,0],["v","Сомнения и к дому их не стянет.",0,1356,0,0],["sp","Хор"],["v","Пока сами мы не увидели,",0,1357,0,0],["v","Что <span class=\"ch\" data-ch=\"elena\">Елена</span> — труп окровавленный.",0,1358,0,0],["sp","Корифей"],["v","Пока из слуг кто вести не принес,",0,1359,0,0],["v","Несчастие я знаю лишь отчасти.",0,1360,0,1],["sp","Хор"],["sd","Отточен правдою, Ты поразил <span class=\"ch\" data-ch=\"elena\">Елену</span>, правды меч! За пагубу, за пагубу Эллады, За пастыря троянского теперь, За слезы жен она ахейских платит."],["sp","Корифей"],["v","Но слышен стук запоров… Тише… Вот",0,1361,0,0],["v","Фригийский раб выходит, и узнаем",0,1362,0,0],["v","Мы, что теперь творится во дворце.",0,1363,0,0],["scene","Явление шестнадцатое","s20",5,20],["sd","После слов корифея из дворца — крадучись, бледный, растерянный, без шапки и в туфлях появляется фригийский раб-евнух."],["sp","Фригиец"],["v","От смерти, от сабли аргосской",0,1364,0,0],["v","На мягких подошвах",0,1370,2,1],["v","Неслышно ушел я:",0,1370,2,0],["v","Над брачным покоем я крался,",0,1371,0,0],["v","И между триглифов дорийских<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,1372,0,0],["v","Не раз застревала нога…",0,1373,0,0],["v","О, дальше отсюда!",0,1373,2,0],["v","Земля, о матерь-земля!",0,1374,0,0],["v","Скажите мне, жены чужие,",0,1375,2,0],["v","Где спрячется варвар?",0,1376,2,0],["v","В волнах ли эфира синих?",0,1376,2,0],["v","Иль море его сохранит,",0,1377,2,0],["v","Покоясь в объятиях бога,",0,1378,2,0],["v","В руках Океана покоясь?",0,1379,2,0],["sp","Корифей"],["v","Но что с тобой, идеец, раб <span class=\"ch\" data-ch=\"elena\">Елены</span>?<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,1380,0,1],["sp","Фригиец"],["v","О Илион, увы! О Илион!",0,1381,0,0],["v","Фригии царство тучной,",0,1382,0,0],["v","Выси Иды священной,",0,1383,0,0],["v","Плачу над вами.",0,1384,0,0],["v","Как азиатская флейта,",0,1385,0,0],["v","Песнью надгробною плачу.",0,1386,0,0],["v","Лебедя дивное чадо,",0,1387,0,0],["v","Трою красой ты сгубила.",0,1388,0,0],["v","Лейся ж, напев гробовой,",0,1390,0,1],["v","И Ганимеду звучи,",0,1390,0,0],["v","Внуку Дардана, проклятьем,",0,1391,0,0],["v","Зевса усладе… Увы мне!",0,1392,0,0],["sp","Корифей"],["v","Но расскажи ж раздельно и ясней,",0,1393,0,0],["v","Что было там — мы по намекам судим.",0,1394,0,0],["sp","Фригиец"],["v","Айлинон, Айлинон! Варвары так<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,1395,2,0],["v","Плач начинают… если царей",0,1396,2,0],["v","Землю окрасит кровь,",0,1397,2,0],["v","Если железо меча",0,1398,2,0],["v","Склонит царя к Аиду.",0,1399,2,0],["v","Вот вам рассказ, о жены:",0,1400,2,1],["v","В доме два льва появились — эллины оба:",0,1400,2,0],["v","Первый был сыном вождя, славного в битвах,",0,1401,0,0],["v","Строфиев другой",0,1402,2,0],["v","Сын был, с Одиссеем",0,1403,2,0],["v","Умыслами злыми",0,1404,2,0],["v","Схож и скрытен так же.",0,1405,2,0],["v","Верен другу был он, дерзок и умен;",0,1405,0,0],["v","А в душе дракон",0,1406,2,0],["v","Был он кровожадный…",0,1407,2,0],["v","Сгибни ж ты, молчун злой и осторожный.",0,1408,2,0],["v","В кресле там сидела милая Париса.",0,1409,0,0],["v","К ней они, и видим — слезы на глазах",0,1410,0,1],["v","У обоих, кротки, на полу садятся,",0,1411,0,0],["v","Тот направо, этот слева, и, руками",0,1412,0,0],["v","Ей обвив колена, умоляя, плачут.",0,1413,0,0],["v","Тут мы невольно отпрянули,",0,1414,2,0],["v","Слуги фригийские, —",0,1415,2,0],["v","Шепот пошел по рядам:",0,1416,2,0],["v","Нет ли коварства тут?",0,1417,2,0],["v","Кто говорит: \"Плакать зачем",0,1420,2,1],["v","Было б разбойникам?\"",0,1391,2,0],["v","Кто говорит: \"Ой, берегись:<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,1362,2,0],["v","Как бы кольцом ее",0,1333,2,0],["v","Змей не обвил, гляди,",0,1304,2,0],["v","Мать удушивший змей\".",0,1275,2,0],["sp","Корифей"],["v","А ты где был тогда? Иль затаился?<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,1246,0,0],["sp","Фригиец"],["v","Я, Фригии помня обычай,",0,1217,2,0],["v","На локоны нежно ей веял,",0,1188,2,0],["v","Ланиты <span class=\"ch\" data-ch=\"elena\">Елены</span>, <span class=\"ch\" data-ch=\"elena\">Елены</span>",0,1159,2,0],["v","Кольцом освежал окрыленным,",0,1130,2,1],["v","Покуда царицы персты",0,1131,2,0],["v","На землю роняли льняные",0,1132,2,0],["v","Из прялки и длинные нити:",0,1133,2,0],["v","Добычи пурпурной фригийской",0,1134,2,0],["v","Сметав поскорее лоскутья,",0,1135,2,0],["v","Сестре Клитемнестре гробницу",0,1136,2,0],["v","Украсить в ней сердце горело.",0,1137,2,0],["v","И говорил <span class=\"ch\" data-ch=\"orest\">Орест</span> жене лаконской:",0,1138,0,0],["v","\"Встань, Дия дочь, о, встань…<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,1139,0,0],["v","Ты к очагу за мною следуй предков\".",0,1440,0,1],["v","И, ничего не думая, она",0,1441,2,0],["v","Пошла за ним.",0,1442,3,0],["v","А фокеец-товарищ кричит:",0,1443,2,0],["v","«Что вы, трусы фригийцы, столпились тут?»",0,1444,2,0],["v","И, сказавши, рабов позамкнул:",0,1445,2,0],["v","Кто в конюшню попал, кто оставлен в дому.",0,1450,2,1],["v","Без защиты осталась царица.",0,1450,2,0],["sp","Корифей"],["v","А дальше что? Иль тут и ужас весь?",0,1451,0,0],["sp","Фригиец"],["v","О матерь, о матерь богов!",0,1452,3,0],["v","О тяжкая, тяжкая мать!",0,1453,3,0],["v","Безбожие, нечестие, напасть —",0,1453,3,0],["v","Всему я был свидетель.",0,1454,3,0],["v","Там в царских чертогах злодеи,",0,1455,2,0],["v","Из пурпурных складок одежды",0,1456,2,0],["v","Украдкою вынув мечи,",0,1456,2,0],["v","Вокруг огляделись тревожно,",0,1457,2,0],["v","Не смотрит ли кто,",0,1458,2,0],["v","И, очи вперив на нее,",0,1459,2,0],["v","Блестящие очи кабанов,",0,1460,2,1],["v","Ей так говорят:",0,1460,2,0],["v","\"Ты умрешь, под мечами умрешь,",0,1461,0,0],["v","А убийца — твой муж <span class=\"ch\" data-ch=\"menelay\">Менелай</span>:",0,1462,0,0],["v","Это он твоей смерти желал,",0,1463,0,0],["v","Когда братом рожденного предал…\"",0,1463,0,0],["v","Завопила, рыдая, жена:",0,1464,2,0],["v","«О, увы мне, увы!» —",0,1465,2,0],["v","И рукой она белую грудь,",0,1466,2,0],["v","А другою чело ударяет…",0,1466,2,0],["v","По чертогу кружит,",0,1467,2,0],["v","Золоченою туфлей сверкая…",0,1468,2,0],["v","Но сурово обутой ногой",0,1469,2,0],["v","Уж аргосец ее настигает,",0,1470,2,1],["v","Пальцы в локоны ей запустил",0,1470,2,0],["v","И уж нежную шею готов",0,1471,2,0],["v","Выше левой лопатки ударить",0,1471,2,0],["v","Своим черным мечом…",0,1472,2,0],["sp","Корифей"],["v","А вы? Иль по углам таились вы?",0,1472,0,0],["sp","Фригиец"],["v","С криком запоры ломаем мы,",0,1473,0,0],["v","Двери повышибли,",0,1474,0,0],["v","Точно быки, разъярились мы.",0,1474,0,0],["v","С камнем один,",0,1475,2,0],["v","А у того праща,",0,1475,2,0],["v","Третий с мечом идет,",0,1476,2,0],["v","Меч-то уж наголо…",0,1477,2,0],["v","Смотрим: <span class=\"ch\" data-ch=\"pilad\">Пилад</span> на нас;",0,1477,2,0],["v","Несокрушим герой:",0,1478,2,0],["v","В Трое, в воротах, я",0,1478,2,0],["v","Видел Приамовых:",0,1479,2,0],["v","Гектор, фригийский царь,",0,1480,2,1],["v","Мог бы сравняться с ним",0,1480,2,0],["v","Или Аякс в своей",0,1481,2,0],["v","Каске о трех гребнях.",0,1482,2,0],["v","Сшиблись мечами мы с силой Ареевой,",0,1483,0,0],["v","Против Эллады нам скоро не мочь пришло,",0,1484,0,0],["v","Наутек пошли, полегли костьми:",0,1485,2,0],["v","Этот раненый, тот уж молится,",0,1486,2,0],["v","В сень укрылись мы,",0,1487,2,0],["v","Полумертвые, в прах попадали,",0,1488,2,0],["v","Лежа, смерти там ждут товарищи.",0,1489,2,0],["v","А Гермиона бедная в тот миг,",0,1490,0,1],["v","Как мать ее ударом сшибли, входит.",0,1490,0,0],["v","Точно вакханки без тирсов,",0,1491,2,0],["v","Кровью, не Вакховым даром,",0,1492,2,0],["v","Пьяны те эллины были.",0,1493,2,0],["v","Зевсову дочь снова колоть хотят.",0,1494,2,0],["v","Смотрим: в чертоге нет уж <span class=\"ch\" data-ch=\"elena\">Елены</span>.",0,1495,2,0],["v","Ты, небо! ты, земля! Вы, свет и ночь!",0,1495,0,0],["v","Каким же волшебством,",0,1496,2,0],["v","Хищением богов, искусством магов",0,1497,0,0],["v","Исчезла <span class=\"ch\" data-ch=\"elena\">Елена</span>?",0,1498,2,0],["v","Стопы я из дома украдкой унес…",0,1499,2,0],["v","О, сколько трудов и сколько страданий",0,1500,2,1],["v","Напрасно подъял <span class=\"ch\" data-ch=\"menelay\">Менелай</span>,",0,1501,2,0],["v","Из Трои жену доставляя…",0,1502,2,0],["sp","Корифей"],["v","За новостью другая: из ворот",0,1503,0,0],["v","<span class=\"ch\" data-ch=\"orest\">Орест</span> с мечом. Уж вот он перед домом,",0,1504,0,0],["v","Поспешною стопой сюда идет.",0,1505,0,0],["scene","Явление семнадцатое","s21",5,21],["sd","Те же и <span class=\"ch\" data-ch=\"orest\">Орест</span> (бодрый, но мрачный по-прежнему; он будто вырос, в руках у него окровавленный меч)."],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Где тут раб, который скрылся от железных рук моих?",0,1506,0,0],["sp","Фригиец"],["dir","падая к его ногам"],["v","Чту обычай азиатский, прах целую ног твоих.",0,1507,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","презрительно, дотрагиваясь до него носком сапога"],["v","Раб, опомнись, здесь не Троя, это — Аргос, греки тут.",0,1508,0,0],["sp","Фригиец"],["v","Будто умные не всюду смерти солнце предпочтут.",0,1509,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","с мрачной шутливостью"],["v","А зачем ты там, в чертогах, к <span class=\"ch\" data-ch=\"menelay\">Менелаю</span> вопиял?",0,1510,0,1],["sp","Фригиец"],["v","Что ты? Звал к тебе ж людей я. Муки мало ль ты подъял?",0,1511,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Значит, дочь была <span class=\"ch\" data-ch=\"tindar\">Тиндара</span> по делам осуждена?",0,1512,0,0],["sp","Фригиец"],["v","Трех смертей <span class=\"ch\" data-ch=\"elena\">Елене</span> мало, столь была она грешна.",0,1513,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Льстишь ты мне, холоп трусливый: и поверил я как раз.",0,1514,0,0],["sp","Фригиец"],["v","Отчего ж и не поверить? Язва — вам, и зло — для нас.",0,1515,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Поклянись под страхом смерти, что правдив был твой ответ.",0,1516,0,0],["sp","Фригиец"],["v","Я душой клянусь, аргосец, и святее клятвы нет.",0,1517,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","играя перед ним мечом"],["v","Вот не так ли донимал вас грек оружием своим.",0,1518,0,0],["sp","Фригиец"],["v","Удали-ка меч, царевич, блеск угрозы нестерпим.",0,1519,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","продолжая"],["v","Голова Горгоны это? Страшно, что ль, окаменеть?",0,1520,0,1],["sp","Фригиец"],["v","Головы такой не знаю, но боюся умереть.",0,1520,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Как, невольник, ты боишься смерти, рвущей узы бед?",0,1521,0,0],["sp","Фригиец"],["v","Будь ты раб или свободен, всем отраден солнца свет.",0,1522,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","опуская меч"],["v","Марш домой! Покуда с тела не слетела голова.",0,1523,0,0],["sp","Фригиец"],["v","Не убьешь?",0,1523,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Прощен, фригиец!",0,1524,0,0],["sp","Фригиец"],["v","Превосходные слова.",1,1524,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Передумал, приготовься: голове скатиться с плеч.",0,1525,0,0],["sp","Фригиец"],["v","Это плохо ты придумал, и бывает лучше речь.",0,1526,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О бессмысленный, неужто думал ты и в самом деле,",0,1526,0,0],["v","Что твоею кровью рабской меч <span class=\"ch\" data-ch=\"orest\">Ореста</span> обагрится?",0,1527,0,0],["v","Ты не женщина, и странно называть тебя мужчиной.",0,1528,0,0],["v","Но зачем же крик ты поднял и меня заставил выйти?",0,1529,0,0],["v","Ведь таким, пожалуй, визгом целый Аргос соберешь ты.",0,1530,0,1],["v","<span class=\"ch\" data-ch=\"menelay\">Менелая</span> мне не страшно — меч в руке ему граница.",0,1530,0,0],["v","Пусть кудрей златисто-белых здесь красой пощеголяет;",0,1531,0,0],["v","Если ж вздумает аргосцев приводить и смерть <span class=\"ch\" data-ch=\"elena\">Елены</span>",0,1532,0,0],["v","Кровью взыскивать с <span class=\"ch\" data-ch=\"orest\">Ореста</span>, осужденных забывая,",0,1533,0,0],["v","Два увидит трупа: возле Тиндариды — Гермиону.",0,1534,0,0],["v","⟨(Уходит во дворец.)⟩",0,1535,4,0],["sp","Хор"],["str","Антистрофа"],["v","Увы мне, увы мне, о, злая судьба!",0,1536,0,0],["v","Злосчастному роду Атридов",0,1537,0,0],["v","Страшнее борьба предстоит.",0,1538,0,0],["sd","⟨Корифей⟩"],["v","Что ж делать нам? Иль Аргос известить?",0,1539,0,0],["v","Или молчать? О да, верней молчанье.",0,1540,0,1],["sp","Хор"],["v","Что за черный дым пред чертогами",0,1541,0,0],["v","Поднимается? Не к добру огонь.",0,1542,0,0],["sd","⟨Корифей⟩"],["v","Взяв факелы, дом Тантала они",0,1543,0,0],["v","Поджечь хотят. Убийства непрерывны.",0,1544,0,0],["sp","Хор"],["sd","Для рода смертного, Где хочет, бог Предел положит там, И бога власть безбрежна — демон зла Кровавых рук от нас не отнимает, С тех пор как в волны свержен был Миртил."],["sp","Корифей"],["v","<span class=\"ch\" data-ch=\"menelay\">Менелай</span> уж к дому близко… как шагает… иль разведал,",0,1545,0,0],["v","Что случилось? Не пора ли на запоры затвориться",0,1550,0,1],["v","Вам, Атриды? Если люди так несчастны, как <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,1550,0,0],["v","Человек носящий имя, муж в удаче им опасен.",0,1551,0,0],["act","Исход","a6",""],["scene","Явление восемнадцатое","s22",6,22],["sd","<span class=\"ch\" data-ch=\"menelay\">Менелай</span> с отрядом. Над портиком <span class=\"ch\" data-ch=\"orest\">Орест</span> и <span class=\"ch\" data-ch=\"pilad\">Пилад</span>. <span class=\"ch\" data-ch=\"orest\">Орест</span> держит у горла Гермионы меч. Гермиона молча стоит на коленях, лицом к отцу. <span class=\"ch\" data-ch=\"menelay\">Менелай</span> вначале не видит происходящего на крыше. Вечер. Кое-где зажигаются огни. На крыше тоже краснеют факелы у рабов."],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Весть принесла ужасные деянья",0,1552,0,0],["v","И дерзкие. Не мужи, звери здесь",0,1553,0,0],["v","Работали, два жадных, диких зверя.",0,1554,0,0],["v","Мне кто-то слух и о жене принес,",0,1555,0,0],["v","Что будто не убита, а бесследно",0,1556,0,0],["v","Из терема исчезла. Этот бред",0,1557,0,0],["v","Пригрезился рассказчику от страха.",0,1558,0,0],["v","А выдумку по свету распустил",0,1559,0,0],["v","Не кто иной, как матереубийца.",0,1560,0,1],["sd","(Стучит в двери.)"],["v","Ну, отпирайте ж двери… Эй, рабы!",0,1561,0,0],["v","Я вырву дочь из рук их оскверненных",0,1562,0,0],["v","И труп жены возьму, — моя рука",0,1563,0,0],["v","Ее убийц накажет смертью тут же.",0,1564,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","сверху"],["v","Эй ты, дверей не порти. На свою",0,1565,0,0],["v","Не много ли ты слишком положился",0,1566,0,0],["v","Отвагу? Ну, как в голову тебе",0,1567,0,0],["v","Карнизом я пущу, сломав старинный",0,1568,0,0],["v","Оплот, работу мастера; и дверь",0,1570,0,1],["v","Заделана, чтоб в ярости бычачьей",0,1571,0,0],["v","Спартанец в дом наш царский не пришел.",0,1572,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","увидев его"],["v","Что вижу я?.. Там факелы сверкают",0,1573,0,0],["v","На портике, как в крепости они, —",0,1574,0,0],["v","И голый меч над дочерью… на страже.",0,1575,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты спрашивать или внимать пришел?",0,1576,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Приходится тебя, как видно, слушать.",0,1577,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Вот дочь твою сбираюсь заколоть…",0,1578,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Или тебе <span class=\"ch\" data-ch=\"elena\">Елены</span> мало было?",0,1579,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Похитил бог добычу у ножа.",0,1580,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Убил ее, да сам еще глумится.",0,1581,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что мне таить?.. Похвастаться бы рад.",0,1582,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Чем хвастаться? Сжимает сердце ужас.",0,1583,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Когда б в Аид чуму спустить я мог.",0,1584,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Отдай мне труп жены для погребенья.",0,1585,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Богов моли. <em>Еще</em> увидишь труп.",0,1586,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Убивши мать, ты жертв уж не считаешь.",0,1587,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Из-за отца, что предан был тобой.",0,1588,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Иль матери ты кровью не пресыщен?",0,1589,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Мне жен лихих казнить не надоест.",0,1590,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","А ты, Пилад, участвовал ли в деле?",0,1591,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Молчанье — знак согласья. Он молчит.",0,1592,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Не торжествуй так рано — ты не птица.",0,1593,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ну что ж?.. И дом мы можем подпалить.",0,1594,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Отцовский дом? Что говоришь? Опомнись.",0,1595,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Отдать тебе? Вот факел, видишь меч?",0,1596,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Что ж, убивай… Сам не уйдешь от кары.",0,1597,0,0],["sd","⟨<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Пусть будет так.",0,1598,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","<em>Нет, нет, остановись</em>.⟩",1,1598,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","В молчании терпи, что заслужил.",0,1599,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","А ты достоин жить?",0,1600,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Достоин царства.",1,1600,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Какого? Здесь?",0,1601,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Пеласгов трон — он мой.",1,1601,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Вот чистый жрец для омовений…",0,1602,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Чистый.",1,1602,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Для жертвы на войне…",0,1603,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не ты ль уж чист?",1,1603,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Руками, да…",0,1604,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Руками, а душою?",1,1604,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Кто б говорил с тобою?",0,1605,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Добрый сын.",1,1605,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","А чтущий мать?",0,1606,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Какой счастливый жребий!",1,1606,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Не твой…",0,1607,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Кому порочные милы?",1,1607,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Меч от нее подальше, меч!",0,1608,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты шутишь?",1,1608,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Иль ты убьешь ее?",0,1609,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Чего же ждать?",1,1609,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Что делать мне? Увы!",0,1610,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Моли аргосцев.",1,1610,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","О чем?",0,1610,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Моли, чтоб не казнили нас.",0,1611,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Иначе вы убьете дочь?",0,1612,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Как видишь.",1,1612,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Несчастная <span class=\"ch\" data-ch=\"elena\">Елена</span>!",0,1613,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А <span class=\"ch\" data-ch=\"orest\">Орест</span>?",1,1613,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Добычу вез тебе я.",0,1614,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Если б мне-то!",1,1614,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Что перенес трудов!",0,1615,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не для меня.",1,1615,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Что выстрадал!",0,1616,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но не на пользу близким.",1,1616,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Твоя взяла.",0,1617,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Сам низостью своею",1,1617,0,0],["v","Ты побежден. Ну, поджигай, Электра!",0,1618,0,0],["v","А ты, мой друг вернейший, обольешь",0,1619,0,0],["v","Горящею смолой стропила эти.",0,1620,0,1],["sd","Минута общей суеты. Только Гермиона стоит молча на коленях."],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","громко, по направлению к Аргосу"],["v","Что медлите, строители Микен,",0,1621,0,0],["v","Табунщики аргосские, спешите",0,1622,0,0],["v","С оружием! Орест, убивший мать,",0,1623,0,0],["v","Здесь силою прощенье вымогает.",0,1624,0,0],["sd","Вдали с криками показывается вооруженная толпа с факелами. Шум, смятение."],["scene","Явление девятнадцатое","s23",6,23],["sd","Внезапно показывается в небе Аполлон, все смолкает, застывает, прилипает к месту. Загоревшиеся было стропила гаснут. Факелы тухнут. На небе показывается свет луны и яркие звезды, между ними одна особенно яркая."],["sp","Аполлон"],["dir","<span class=\"ch\" data-ch=\"menelay\">Менелаю</span>"],["v","Смири свой гнев, Атрид! Перед тобой",0,1625,0,0],["v","Латоны сын и просит: «Успокойся».",0,1626,0,0],["sd","(<span class=\"ch\" data-ch=\"orest\">Оресту</span>.)"],["v","И ты мечом девице угрожать",0,1627,0,0],["v","Повремени, Орест! Внемлите богу.",0,1628,0,0],["sd","(<span class=\"ch\" data-ch=\"orest\">Оресту</span>.)"],["v","Разгневанный на <span class=\"ch\" data-ch=\"menelay\">Менелая</span>, ты",0,1630,0,1],["v","Его жену убить хотел… Глядите,",0,1630,0,0],["v","Там, в глубине эфирной, уж звездой",0,1631,0,0],["v","Она горит и смерти избежала.",0,1632,0,0],["v","Я спас ее из-под ножа. Так Зевс-",0,1633,0,0],["v","Отец велел. Он дочери бессмертной",0,1634,0,0],["v","Дал светлый трон в обители небес,",0,1635,0,0],["v","Чтоб с Кастором она и Полидевком",0,1636,0,0],["v","Спасением сияла для пловцов.",0,1637,0,0],["v","Ты, Менелай, возьмешь жену другую;<a class=\"nr\" href=\"#n-k39\" data-n=\"k39\" aria-label=\"Примечание 39\">39</a>",0,1638,0,0],["v","Ее красой бессмертные вражду",0,1639,0,0],["v","Меж вас зажгли, где столько и фригийцев",0,1640,0,1],["v","И эллинов погибло, чтобы тем",0,1641,0,0],["v","Освободить вам землю от наплыва",0,1642,0,0],["v","Преступного и дерзкого. <span class=\"ch\" data-ch=\"orest\">Орест</span>,",0,1643,0,0],["v","Покинь предел аргосский и пробудь",0,1644,0,0],["v","В Паррасии, покуда год свершится.",0,1645,0,0],["v","Азанцы и аркадяне его",0,1646,0,0],["v","Именовать положат Орестеем,<a class=\"nr\" href=\"#n-k40\" data-n=\"k40\" aria-label=\"Примечание 40\">40</a>",0,1647,0,0],["v","Тебя почтив. Оттуда ты пойдешь",0,1648,0,0],["v","В Афины — там трем Евменидам должен",0,1650,0,1],["v","Ты будешь дать ответ за то, что мать",0,1650,0,0],["v","Убил: ты там судим богами будешь",0,1651,0,0],["v","И на холме Арея победишь.",0,1652,0,0],["v","Тебе судьба в невесты Гермиону",0,1653,0,0],["v","Из-под ножа готовит. Никогда",0,1654,0,0],["v","Неоптолем ее не будет мужем.",0,1655,0,0],["v","Он от меча дельфийского падет,",0,1655,0,0],["v","Мной за отца наказан, за Пелида…",0,1656,0,0],["v","Ты обещал <span class=\"ch\" data-ch=\"pilad\">Пиладу</span> дать сестру:<a class=\"nr\" href=\"#n-k41\" data-n=\"k41\" aria-label=\"Примечание 41\">41</a>",0,1657,0,0],["v","Отдай ее — <span class=\"ch\" data-ch=\"elektra\">Электру</span> ждет блаженство.",0,1658,0,0],["sd","(<span class=\"ch\" data-ch=\"menelay\">Менелаю</span>.)"],["v","Ты ж, Менелай, оставь его царить",0,1659,0,0],["v","Над Аргосом, и Спартой будь доволен,",0,1660,0,1],["v","Наследием жены: она тебе",0,1661,0,0],["v","Бесчисленных трудов и бесконечных",0,1662,0,0],["v","Покуда стоила, и только. Я ж дела",0,1663,0,0],["v","Орестовы улажу, потому что",0,1664,0,0],["v","Приказ убить был точно мой приказ.",0,1665,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","бросая меч"],["v","О вещий бог! Воистину, оракул",0,1666,0,0],["v","Твой справедлив. А уж боялся я,",0,1667,0,0],["v","Что демона за Аполлона принял.",0,1668,0,0],["v","Все кончилось ко благу. И, тебе",0,1670,0,1],["v","Покорный, я оставил Гермиону,",0,1670,0,0],["v","А даст отец — женой ее возьму.",0,1671,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","обращаясь к новой яркой звезде"],["v","О Зевса дочь, прости, прости, Елена!",0,1672,0,0],["v","Блаженна ты в обители богов…",0,1673,0,0],["v","Мне Феба речь — закон, и дочь <span class=\"ch\" data-ch=\"orest\">Оресту</span>",0,1674,0,0],["v","Я отдаю. Коль знатен человек",0,1675,0,0],["v","И женится на знатной — брак завиден.",0,1676,0,0],["v","Ну, в добрый час, обоим в добрый час!",0,1677,0,0],["sp","Аполлон"],["v","Как сказано, исполните, а ссоры",0,1678,0,0],["v","Пора забыть.",0,1679,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Склоняюсь пред тобой.",1,1679,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Таков и я: небесные слова",0,1680,0,1],["v","Запомнил я и в сердце сберегу их.",0,1680,0,0],["sp","Аполлон"],["v","Из богинь почтите теперь",0,1681,0,0],["v","Тишину, нет дивной прекрасней.",0,1682,0,0],["v","Чрез море блестящих светил",0,1683,0,0],["v","Я пойду провожать <span class=\"ch\" data-ch=\"elena\">Елену</span>",0,1683,0,0],["v","До чертога Кронида, жену…<a class=\"nr\" href=\"#n-k42\" data-n=\"k42\" aria-label=\"Примечание 42\">42</a>",0,1684,0,0],["v","Рядом с Герой и Гебой воссев,",0,1685,0,0],["v","Обрученной Гераклу, она",0,1686,0,0],["v","Станет богом для смертных отныне,",0,1686,0,0],["v","На фиалы с небес улыбаясь,",0,1687,0,0],["v","Корабли она будет хранить,",0,1688,0,0],["v","Как и вы, сыновья <span class=\"ch\" data-ch=\"tindar\">Тиндара</span>,",0,1689,0,0],["v","Будет в небе отрадой пловцов.",0,1690,0,1],["sp","Хор"],["v","Благовонной короной своей",0,1691,0,0],["v","Увенчай поэта, победа,",0,1692,0,0],["v","И не раз, и не два, и не три",0,1693,0,0],["v","Ты увей ему белые кудри.",0,1694,0,0],["h1","Комментарий","comm"],["p","В трагедии, поставленной в 408 г. до н. э., Еврипид обращается к той части сказания об Оресте, которая касается его судьбы после совершения мести убийцам отца. Однако если в предшествующих произведениях («Ифигения в Тавриде», ст. 940 — 969, и «Электра», ст. 1250 — 1272) драматург в общем принимал традиционный для Афин вариант мифа (Орест перед судом Ареопага), то здесь он касается его только мимоходом (ст. 1648 — 1652), предлагая взамен вниманию зрителей свою собственную, совершенно необычную версию: преступление Ореста становится предметом обсуждения в народном собрании в Аргосе, которое выносит убийце матери смертный приговор; в поисках спасения Орест громоздит одну кровавую авантюру на другую, пока вмешательство Аполлона не дает разрешения окончательно запутавшейся интриге."],["p","Среди других трагедий Еврипида «Орест» выделяется повышенным интересом автора к музыкальной стороне исполнения: как указывают античные комментаторы, не только в большой арии фригийца, но и в хоровых партиях выбор слов в значительной мере подчинен мелодическому рисунку. Подтверждение этому дает также найденный в конце прошлого века папирусный фрагмент первого стасима, снабженный нотными знаками и пометками для исполнителей."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"],["note","k39"],["note","k40"],["note","k41"],["note","k42"]],"n":{"k1":["Ст. 10. …С надменным царь не сладил языком.","Еврипид несколько видоизменяет миф, приписывая Танталу не разглашение тайны, а дерзкие речи во время самого пира богов; он принимает также какую-то малоизвестную версию, согласно которой Тантал был подвешен на цепи между небом и землей, в то время как над ним нависала угрожающая падением скала (см. также ст. 982 — 987)."],"k2":["Ст. 63 — 66. …с нею здесь дочь-девушка…","Пребывание Гермионы в доме Клитемнестры — нововведение Еврипида."],"k3":["Ст. 256 — 261","В изображении Эриний Еврипид находится под влиянием Эсхила (ср. «Хоэфоры», ст. 1048 — 1058, и «Евмениды», ст. 49 — 56)."],"k4":["Ст. 268 — 270. …лук… Аполлонов подарок…","Деталь, заимствованная из «Орестеи» Стесихора."],"k5":["Ст. 347. Он наследье браков небесных.","Тантал родился от Зевса и нимфы Плуто и, в свою очередь, женился на Дионе, дочери Атланта."],"k6":["Ст. 362 — 374. Главк","морское божество, обладавшее даром прорицания, — играет здесь роль, которую в «Одиссее» исполняет Протей (см. IV, 512 — 547). Свое прибытие в Навплию Менелай объясняет как раз полученным от Главка известием: оно заставило его изменить маршрут и вместо Спарты направиться в Аргос, разумеется, по суше, так как водного пути между Навплией и Аргосом нет. Поэтому слова «сюда Елена… стиралась плыть» — недосмотр переводчика."],"k7":["Ст. 388. Не вид","душа меня, душа порочит. — В подлиннике: «Не вид — дела…»"],"k8":["Ст. 396","Очень важный стих, в котором действительно встречается понятие «совесть» (см. примеч. к «Медее», ст. 1054, и к «Андромахе», ст. 822 — 824), переведен неточно. Смысл оригинала: «Совесть, ибо я понимаю ужас совершенного». <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Медея», Ст. 1054. …совесть… не позволяет….</b> В оригинале речь идет не о совести (это понятие только появляется в V в. и встречается у Еврипида еще редко), а о тех, «кому не подобает присутствовать» при этом жертвоприношении.</span><!--/xn--> <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Андромаха», Ст. 822-824. …преступной совести….</b> Здесь, как и в «Медее» (см. примеч. к ст. 1054), в оригинале нет ни слова о «преступной совести» Гермионы; сказано только: «Кажется, несчастная покажет, насколько она страдает, совершив преступление». Как видно из дальнейшего, Гермиону мучит вовсе не совесть, а страх перед Неоптолемом.</span><!--/xn-->"],"k9":["Ст. 432 сл. Эак","брат Паламеда (см. примеч. к «Елене», ст. 766 — 769); этим объясняется его вражда к роду Агамемнона. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Елена», Ст. 766 — 769.</b> На обратном пути из Трои ахейские корабли попали в Эгейском море в сильную бурю (см. Эсхил, «Агамемнон», ст. 650 — 660; Еврипид, «Троянки», ст. 77 — 94), во время которой многие погибли. Старец Еврейский — Навплий, отец Паламеда, казненного греками под Троей по ложному обвинению; чтобы отметить им за смерть сына, Навплий при приближении уцелевших от бури кораблей к Евбее зажег ложный маяк над подводными утесами («огни коварные»), на которых разбились многие корабли. Сам Менелай был застигнут новой бурей у мыса Малеи (см. ст. 1132), отнесен далеко на запад и во время своих семилетних скитаний (см. ст. 775 сл.) посетил и критские города, и ливийские гавани. Под нагорными вышками Персея разумеется какая-то область в Ливии, где Персей спас от морского чудовища прикованную к скале Андромеду. Этот миф был обработан Еврипидом в трагедии «Андромеда», поставленной одновременно с «Еленой», но не сохранившейся.</span><!--/xn-->"],"k10":["Ст. 440. …суд… черепков…","неточный перевод греческого слова psephos, обозначающего камешек для голосования: белые камешки клали в урну в знак оправдания, черные — в знак обвинения подсудимого. Что касается черепков (греч. ostrakon), то на них писали имя гражданина, осуждаемого на изгнание."],"k11":["Ст. 474. …направо став…","По греческим поверьям, всякая встреча с правой стороны была благоприятным знамением."],"k12":["Ст. 485. Меж варваров…","Намек на длительное скитание Менелая после взятия Трои."],"k13":["Ст. 495 — 525","Тиндарей излагает точку зрения афинского уголовного права: убийцу надлежит карать изгнанием, а не убивать, иначе по закону кровной мести всегда останется виновный."],"k14":["Ст. 527 сл. …освобождая грудь, молила мать…","Ср.: Эсхил, «Хоэфоры», ст. 896 — 898, и Еврипид, «Электра», ст. 1206 — 1209."],"k15":["Ст. 552 — 554","Аргументы Ореста в пользу приоритета отца заимствованы из «Евменид» Эсхила, ст. 658 — 661:<br>Та, что зовется матерью, не создает<br>Дитя, лишь плод она растит посеянный.<br>Творит зачинщик. А она залог хранит,<br>Как гостю гость, когда не повредит ей бог."],"k16":["Ст. 573 — 575. …Над кем она глумиласъ?","Опять аргумент, заимствованный у Эсхила («Евмениды», ст. 625 — 630)."],"k17":["Ст. 591. Пуп земной…","Считалось, что центром земного круга является круглый камень посреди дельфийского храма Аполлона."],"k18":["Ст. 751. …. поднял лай…","«Позволяю себе эту метафору ввиду эсхиловского »hylagmaton« (Agam. 1643)» (примеч. И. Анненского). В подлиннике просто: «разгневался»."],"k19":["Ст. 765. Строфий… отлучены произнес.","Изгнание Пилада — тоже нововведение Еврипида."],"k20":["Ст. 813. Из-за златого… руна…","См. примеч. к «Ифигении в Тавриде», ст. 194 — 200. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ифигения в Тавриде», Ст. 194-200. Гелия яркое око….</b> Речь идет о вражде детей Пелопа — Атрея и Фиеста. В стаде Атрея появился златорунный ягненок, и прорицатели истолковали это как знамение, дающее Атрею право на царский престол в Аргосе. Фиест, соблазнив жену Атрея Аэропу, выкрал при ее помощи златорунного ягненка и предъявил его в народном собрании, претендуя на царскую власть. Тогда Зевс по просьбе Атрея послал новое знамение, подтверждающее его права: солнце изменило свой прежний путь и стало передвигаться с запада на восток.</span><!--/xn-->"],"k21":["Ст. 815. …ужин из царских детей…","Чтобы отомстить Фиесту за вероломство, Атрей под видом примирения с братом пригласил его на пир и подал мясо убитых им детей Фиеста."],"k22":["Ст. 872. …чтоб дать ответ Египту…","Согласно одному из вариантов сказания о Данаидах их отец Данай был вызван на суд его братом Египтом, отцом убитых женихов."],"k23":["Ст. 888","Талфибий известен уже из «Илиады» как вестник Агамемнона и исполнитель его поручений. В этой роли он выступает также у Еврипида в «Гекубе», «Троянках» и «Ифигении в Авлиде»."],"k24":["Ст. 902 — 906","В этой характеристике уже древние видели намек на афинского политического деятеля Клеофонта, противника мирных переговоров со Спартой. Будучи по матери фракийского происхождения, он сумел тем не менее получить гражданские права и занять видное место в Афинах; отсюда — «навязанный аргосец» (в оригинале: «аргосец, но не аргосец»)."],"k25":["Ст. 907 — 913","Стихи, заключенные в скобки, издатели считают позднейшей вставкой, нарушающей течение рассказа вестника."],"k26":["Ст. 917 — 922. …встает оратор…","Идеальный образ независимого гражданина-земледельца, не поддающегося безответственной пропаганде ораторов."],"k27":["Ст. 960 — 1011","Некоторые исследователи считают, что исполнителем первой пары симметричных строф является хор и только следующие четыре строфы без соответствующих ритмических параллелей составляют монодию Электры."],"k28":["Ст. 964. В усладу богине","Персефоне."],"k29":["Ст. 988 — 994","См. примеч. к «Ифигении в Тавриде», ст. 191 — 193. Герест — горный мыс на южной оконечности Евбеи. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ифигения в Тавриде», Ст. 191-193.</b> Греческий текст дошел здесь в плохой сохранности, и переводчик дает скорее пояснение, чем перевод. Чтобы добиться руки дочери Эномая (ср. ст. 1 сл.), Пелоп должен был обогнать его в состязании на колесницах; неудачливых претендентов Эномай убивал. Пелоп подкупил Миртила, возницу Эномая, который вынул болт из чеки колесницы своего господина, и таким образом Пелоп одержал победу. Впоследствии, чтобы избавиться от свидетеля своего преступления, он столкнул Миртила в море.</span><!--/xn-->"],"k30":["Ст. 1168. …властью тирана не владея…","Орест хочет сказать, что Агамемнон, хотя и не был единоличным владыкой Эллады, пользовался в ней авторитетом по праву лучшего. Ту же мысль высказывает о себе самом Менелай в «Елене», ст. 395."],"k31":["Ст. 1227. К тебе мольбу склоняем мы…","Стихи 1227 — 1230 являются скорее всего более поздней вставкой; их не было в изданиях античного времени, и они нарушают ритм молитвы, в которую каждый из участников предстоящего предприятия вступает репликой из двух стихов: 1225 сл. — Орест, 1231 сл. — Электра, 1233 сл. — Пилад."],"k32":["Ст. 1233. …от родича мольбу…","Пилад — племянник Агамемнона, сын его сестры Анаксибии."],"k33":["Ст. 1246 — 1352","Позиция Электры в этой сцене близко напоминает ее роль в «Электре» Софокла, ст. 1398 — 1465. Разница только в том, что там творится правая месть, здесь — новая жестокость."],"k34":["Ст. 1353 — 1365","Симметричную антистрофу составляют ст. 1537 — 1549, предвещающие появление Менелая."],"k35":["Ст. 1365. За пастыря Троянскою","за Париса."],"k36":["Ст. 1372. Триглиф","часть фриза, представляющая продолговатую плиту с вырезанными желобами."],"k37":["Ст. 1380. Идеец","то есть родившийся в окрестностях горы Иды."],"k38":["Ст. 1395. Айлинон.","По объяснению исследователей, это восклицание восходит к семитскому «ай лену» («горе нам!») и пришло в Грецию из Финикии. Впрочем, Эсхил в «Агамемноне», ст. 121, 139, 159, влагает его в уста аргосских старцев."],"k39":["Ст. 1638. Ты, Менелай, возьмешь жену другую…","Вариант, не известный ни из каких других источников."],"k40":["Ст. 1645 — 1647. Паррасия","область на юге Аркадии (центральный Пелопоннес); азанцы — жители области Азании в северной Аркадии. Пребывание Ореста в течение года в Аркадии является, вероятно, нововведением Еврипида, которое он мог обосновать значительным распространением в этой области мифов об Оресте."],"k41":["Ст. 1653 — 1657","См. трагедию «Андромаха» и комментарий к ней."],"k42":["Ст. 1684. …почтите теперь Тишину…","В оригинале богиня названа Eirene, что соответствует русскому понятию «мир». После поражения спартанцев при Кизике (весной 410 г.) с их стороны дважды делались мирные предложения, которые отвергались сторонниками продолжения войны во главе с Клеофонтом (см. примеч. к ст. 902 — 906). Еврипид, как видно из этих стихов, не разделял подобных воинственных настроений. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 902 — 906.</b> В этой характеристике уже древние видели намек на афинского политического деятеля Клеофонта, противника мирных переговоров со Спартой. Будучи по матери фракийского происхождения, он сумел тем не менее получить гражданские права и занять видное место в Афинах; отсюда — «навязанный аргосец» (в оригинале: «аргосец, но не аргосец»).</span><!--/xn-->"]},"mainEnd":2619,"c":[{"id":"orest","name":"Орест","role":"Сын Агамемнона, матереубийца","intro":"Больной безумием юноша, которого город собирается казнить за убийство матери.","arc":"Пьеса начинается на шестой день после убийства Клитемнестры: Орест лежит в лихорадке, его мучают Эринии. Его последняя надежда — дядя Менелай, но тот предаёт. Осуждённый народным собранием на смерть, Орест вместе с Пиладом и Электрой решается на отчаянный план: убить Елену и взять в заложницы Гермиону. Финал — Орест на крыше дворца с мечом у горла девушки — разрешается лишь появлением Аполлона.","st":[{"i":491,"p":19,"l":"Действие первое · явление пятое","t":"Пробуждение","d":"Просыпается, мучимый видениями Эриний; Электра ухаживает за ним.","c":"","k":false},{"i":742,"p":28,"l":"Действие второе · явление шестое","t":"Мольба к Менелаю","d":"Умоляет дядю заступиться за него в суде.","c":"","k":false},{"i":1072,"p":41,"l":"Действие второе · явление восьмое","t":"Предательство","d":"Менелай отказывается помочь силой.","c":"Последняя надежда исчезает.","k":true},{"i":1291,"p":49,"l":"Действие второе · явление десятое","t":"Пилад","d":"Друг идёт с ним на собрание.","c":"","k":false},{"i":1477,"p":56,"l":"Действие третье · явление двенадцатое","t":"Приговор","d":"Вестник рассказывает: собрание приговорило Ореста и Электру к смерти, позволив покончить с собой.","c":"","k":false},{"i":1923,"p":73,"l":"Действие третье · явление четырнадцатое","t":"Заговор","d":"С Пиладом и Электрой решает убить Елену и взять Гермиону в заложницы.","c":"Жертва становится мстителем.","k":true},{"i":2362,"p":90,"l":"Действие четвертое · явление семнадцатое","t":"Фригиец","d":"Настигает беглого раба, но щадит его и отпускает.","c":"","k":false},{"i":2527,"p":97,"l":"Исход · явление восемнадцатое","t":"На крыше","d":"С мечом у горла Гермионы угрожает Менелаю и готов поджечь дворец.","c":"","k":false},{"i":2618,"p":100,"l":"Исход · явление девятнадцатое","t":"Воля Аполлона","d":"Бог приказывает ему взять в жёны Гермиону и идти на суд в Афины.","c":"","k":false}],"gen":"Орест"},{"id":"elektra","name":"Электра","role":"Сестра Ореста","intro":"Сестра, ухаживающая за братом и разделяющая его участь.","arc":"Электра здесь — сиделка и соучастница: она нежна к брату, ненавидит Елену и сама предлагает взять Гермиону в заложницы.","st":[{"i":113,"p":4,"l":"Пролог · явление первое","t":"Пролог","d":"Рассказывает о преступлении и о болезни брата.","c":"","k":false},{"i":491,"p":19,"l":"Действие первое · явление пятое","t":"У постели брата","d":"Успокаивает Ореста в припадке безумия.","c":"","k":false},{"i":1477,"p":56,"l":"Действие третье · явление двенадцатое","t":"Приговор","d":"Узнаёт, что приговорена вместе с братом.","c":"","k":false},{"i":1923,"p":73,"l":"Действие третье · явление четырнадцатое","t":"План заложницы","d":"Предлагает захватить Гермиону.","c":"","k":true},{"i":2107,"p":80,"l":"Действие четвертое · явление пятнадцатое","t":"Захват Гермионы","d":"Заманивает Гермиону во дворец.","c":"","k":false}],"gen":"Электра"},{"id":"menelay","name":"Менелай","role":"Царь Спарты","intro":"Дядя, на помощь которого надеется Орест.","arc":"Менелай слаб и расчётлив: он боится народа и не хочет рисковать ради племянника.","st":[{"i":742,"p":28,"l":"Действие второе · явление шестое","t":"Возвращение","d":"Прибывает из Трои и видит Ореста больным.","c":"","k":false},{"i":1072,"p":41,"l":"Действие второе · явление восьмое","t":"Отказ","d":"Отказывается помочь силой, обещает лишь уговоры.","c":"","k":true},{"i":2527,"p":97,"l":"Исход · явление восемнадцатое","t":"Бессилие","d":"Видит дочь с мечом у горла и не может ничего сделать.","c":"","k":false}],"gen":"Менелай"},{"id":"elena","name":"Елена","role":"Жена Менелая","intro":"Виновница войны, которую ненавидит Электра.","arc":"Елена здесь мелочна и тщеславна: она боится показаться людям и посылает дочь на могилу сестры. В момент убийства она исчезает — Аполлон берёт её на небо.","st":[{"i":211,"p":8,"l":"Пролог · явление второе","t":"Возлияние","d":"Просит Электру отнести дары на могилу Клитемнестры.","c":"","k":false},{"i":2273,"p":87,"l":"Действие четвертое · явление шестнадцатое","t":"Исчезновение","d":"Фригиец рассказывает, как Елена исчезла из-под мечей.","c":"","k":true}],"gen":"Елена"},{"id":"tindar","name":"Тиндар","role":"Отец Клитемнестры и Елены","intro":"Старик, требующий казни внука.","arc":"Тиндар обличает Ореста: месть следовало совершить по закону, а не кровью.","st":[{"i":962,"p":37,"l":"Действие второе · явление седьмое","t":"Обвинение","d":"Обвиняет Ореста и угрожает Менелаю.","c":"","k":true}],"gen":"Тиндар"},{"id":"pilad","name":"Пилад","role":"Друг Ореста","intro":"Верный друг, разделяющий все замыслы Ореста.","arc":"Пилад — человек действия: он предлагает убить Елену.","st":[{"i":1291,"p":49,"l":"Действие второе · явление десятое","t":"Верность","d":"Отказывается покинуть друга.","c":"","k":false},{"i":1923,"p":73,"l":"Действие третье · явление четырнадцатое","t":"План","d":"Предлагает убить Елену.","c":"","k":true}],"gen":"Пилад"}]};
